pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class penalties.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 20.0;
    } else if post_residual <= 35 {
        score += 8.0;
    } else if post_residual <= 50 {
        score -= 4.0;
    } else {
        score -= 10.0;
    }

    // Harmonic modulo nudges.
    let m = post_residual % 10;
    if post_residual > 0 && m == 0 {
        score -= 6.0;
    } else if m == 1 || m == 9 {
        score += 3.0;
    } else if m == 2 || m == 8 {
        score += 2.0;
    }

    // Lookahead chaining (borrowed strength from best-known): reward bins whose
    // post_residual can host the next item tightly, penalize unusable leftovers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            // A near-perfect two-step chain: reward extra.
            if second_post == 0 {
                score -= 60.0;
            } else if second_post < 10 {
                score -= 30.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else if post_residual < 30 {
                score += 6.0;
            }
        }
    }

    // Last-chance: sole fitting open bin is precious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate baseline: neutral-to-slightly-negative, so it only wins
    // when every open bin would leave bad leftovers.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 70.0 + 0.3 * mean_residual - 15.0 * (1.0 - progress) - 1.0 * open_bins_count as f64;
        // If the best open-bin fit would waste <15% capacity, opening fresh is bad.
        if post_residual > 0 && (post_residual as f64) / cap < 0.15 && bin_residual != bin_capacity {
            score += 20.0;
        }
    }

    // Best-fit bias toward tighter-than-mean bins.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted after placement

    // Dead-space class penalties: leftovers that few future items can use.
    // Class A: post_residual in (0, 10] -> almost unusable, heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    }
    // Class B: (10, 20] -> only tiny items fit.
    else if post_residual <= 20 {
        score += 20.0;
    }
    // Class C: (20, 35] -> moderate dead space.
    else if post_residual <= 35 {
        score += 8.0;
    }
    // Class D: (35, 50] -> half bin, still useful.
    else if post_residual <= 50 {
        score -= 4.0;
    }
    // Class E: > 50 -> large residual, very desirable.
    else {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: "harmonic" multiples of 10 align with
    // common item-size classes; exact multiples of 10 are prime reuse targets.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Residuals that are 1 or 2 away from a multiple of 10 are near-class fits.
    let m = post_residual % 10;
    if m == 1 || m == 9 {
        score += 3.0;
    } else if m == 2 || m == 8 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally to how well next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
        } else {
            // Next item cannot use this residual at all: penalize small leftovers.
            if post_residual < next_item_size && post_residual < 30 {
                score += 6.0;
            }
        }
    }

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over
    // opening a new bin, especially when residual is small (tight packing).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin starts from a neutral baseline.
    if bin_residual == bin_capacity {
        // New bin is fine early in the stream or when few bins are open and
        // current mean residual is already large (poor fits everywhere).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        // Discourage opening new bins when existing bins have small residuals.
        score = 55.0 + 0.5 * mean_residual - 20.0 * (1.0 - progress) - 1.5 * open_pressure;
        // If the current bin would leave a terrible leftover, opening fresh is OK.
        if frac < 0.15 && post_residual > 0 && bin_residual != bin_capacity {
            score -= 10.0;
        }
    }

    // Slight global preference for bins tighter than the mean (best-fit bias).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

