    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    let m = post_residual % 10;
    if m == 1 || m == 9 {
        score += 3.0;
    } else if m == 2 || m == 8 {
        score += 2.0;
    }

    // Strong lookahead chaining: reward bins whose leftover serves the next item,
    // with extra reward when the second leftover would also be tiny.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            } else if second_post % 10 == 0 {
                score -= 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // A leftover that just misses the next item is nearly useless.
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline high enough that only genuinely bad fits
    // among open bins justify opening a new one.
    if bin_residual == bin_capacity {
