}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small.
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Penalize leaving dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot follow here; slight penalty proportional to mismatch
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it's chosen
    // only when fits into open bins are poor.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening new bins is more attractive early (more future items to fill it)
        // and when open bins are already numerous/fragmented.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
        score -= (open_bins_count as f64).powi(2) * 0.05;
    } else {
        // Slight preference to fill already-open bins as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
    }

    // Global state: if mean residual across bins is high, encourage consolidating
    // into bins with residual near mean (avoid fragmenting spread).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // minimum item (1) are useless; penalize small nonzero residuals hard.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward residuals that can still fit a typical upcoming item
    // (post_residual >= next_item_size keeps the bin useful).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * (post_residual as f64 - next_item_size as f64).min(30.0);
        } else {
            // This placement strands the bin relative to the next item.
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid spreading; with few open bins, opening a new one is cheap.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: make it attractive only when current bins are
    // crowded (high mean fill) or the fit would create dead space.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += 15.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure waste.
    if post_residual < 10 {
        // Perfect or near-perfect fill is excellent; small-but-nonzero dead space is bad.
        score -= 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize residuals that can only fit very few future sizes (tight gap).
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * tightness;

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would leave a new dead gap, penalize slightly.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 8.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score = 60.0 - 4.0 * crowded;
        // Opening a new bin is bad if this bin would be a near-perfect fit.
        if post_residual < 15 {
            score += 50.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in classes of 10
    let dead_class = post_residual / 10;
    // Penalize residual classes that are hard to fill (1..9, 11..19 etc. -> small residuals)
    if post_residual > 0 {
        let small = if post_residual < 10 { 1.0 } else { 0.0 };
        score += small * 15.0;
        // modulo structure: residuals of form 0 mod 10 are ideal
        if post_residual % 10 == 0 { score -= 6.0; }
        else { score += (post_residual % 10) as f64 * 0.4; }
    } else {
        score -= 12.0; // perfect fit
    }

    // Deep dead-space penalty for very small unusable residuals
    if post_residual > 0 && post_residual <= 5 {
        score += 20.0;
    }

    // Fit tightness: reward minimizing waste relative to item size
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 { score -= 25.0; }
        else if slack % 10 == 0 { score -= 15.0; }
        else { score -= 8.0 - slack as f64 * 0.2; }
    } else if next_item_size > post_residual {
        // next item cannot follow here; penalize slightly more when this bin was the only option
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let early = (step_index as f64) / (total_items.max(1) as f64);
        // base cost of a fresh bin, reduced later in the stream when fragmentation is high
        score = bin_capacity as f64 * 0.85 - pressure * 2.0 - early * 10.0;
        if mean_residual > item_size as f64 + 10.0 {
            score += 15.0; // open bins still have room; don't open new
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (fill crowded bins first)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // divisibility rewards: post space reusable in whole chunks
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // half-capacity residuals are highly reusable
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 5.0;
        }
        // stranded-slice guard
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let remaining_frac = 1.0 - progress;
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            score += 4.0 * (next_item_size - post_residual) as f64 * remaining_frac;
        }
        // common small denominators
        if post_residual >= 4 && post_residual % 4 == 0 {
            score -= 1.5;
        }
        // dead-space penalty: small useless gaps heavily penalized
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0;
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            // multi-item chaining lookahead
            let m = next_item_size.min(item_size).max(1);
            if second_post >= m { score -= 6.0; }
            if second_post >= 2 * m { score -= 4.0; }
            if second_post >= 3 * m { score -= 2.0; }
            if second_post >= 4 * m { score -= 1.5; }
            if second_post >= 5 * m { score -= 1.0; }
            let chain_val = (m as f64) * (1.0 - 0.85_f64.powi((second_post / m) as i32 + 1));
            score -= 0.15 * chain_val * (1.0 - progress);
            if second_post % 5 == 0 && second_post > 0 {
                score -= 2.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // open-bin pressure
    score += 0.6 * open_bins_count as f64;

    if bin_residual == bin_capacity {
        // new-bin candidate
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        score += 15.0 * progress;
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 30.0 * (progress - 0.7) / 0.3;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && progress < 0.6 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
        // open fresh when item nearly fills a bin and existing fits leave large gaps
        if item_size as f64 >= 0.8 * bin_capacity as f64 && fitting_bins_count >= 1 && progress < 0.85 {
            score -= 12.0;
        }
        // open fresh when residual left behind would be tiny and unusable
        if post_residual > 0 && next_item_size > 0 && post_residual < (next_item_size / 2) && fitting_bins_count >= 2 && progress < 0.8 {
            score -= 8.0;
        }
        // medium-large items early in stream benefit from fresh bin
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
    } else {
        // prefer filling already-loaded bins, more so late in stream
        let fill = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 * fill + 3.0 * progress * fill;
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 { score -= 8.0; }
            if slack == 0 { score -= 6.0; }
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 5.0;
        }
        if progress > 0.75 {
            score += 5.0 * fill * (progress - 0.75) / 0.25;
        }
        if progress > 0.85 && post_residual == 0 {
            score -= 10.0 * (progress - 0.85) / 0.15;
        }
        // mid-stream: penalize bins with large waste fraction
        if progress > 0.3 && progress < 0.85 && post_residual > 0 {
            let waste_frac = 1.0 - fill;
            score += 2.0 * waste_frac * (1.0 - progress);
        }
    }

    // dead-space guard: strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
        score += 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / usable_floor.max(1) as f64);
    }

    // near-perfect compaction reward
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            // Keep a usable second gap if possible.
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowded-field residual alignment: among many fitting bins, prefer
    // residuals close to the mean (avoids leaving outliers half-used).
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Only open a new bin when existing bins are very crowded.
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += 15.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // Big items justify a fresh bin; also allow opening when the stream
        // has plenty of remaining items to fill the new bin with.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
        let remaining = total_items.saturating_sub(step_index) as f64;
        score -= 0.05 * remaining;
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
