    let progress = step_index as f64 / total_items . max (1) as f64 ;
    let remaining = total_items . saturating_sub (step_index) ;
    let min_next = if next_item_size > 0 { next_item_size . min (item_size) } else { item_size } ;
    let adaptive_floor = ((min_next as f64) . max (mean_residual . max (0.0) * 0.35) . min (bin_capacity as f64 * 0.5)) as u32 ;
    if post_residual == 0 {
        score -= 1000.0 ;
