        if item_size > 0 && post_residual % item_size == 0 { score -= 10.0 ; }
        if next_item_size > 0 && post_residual % next_item_size == 0 { score -= 6.0 ; }
        let half = bin_capacity / 2 ;
        if post_residual . abs_diff (half) <= 2 { score -= 5.0 ; }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let remaining_frac = 1.0 - progress ;
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64) ;
            score += 4.0 * (next_item_size - post_residual) as f64 * remaining_frac ;
        }
