        }
        if post_residual > 0 && post_residual < 8 { score += 2.0 * (1.0 - progress) ; }
        // new: penalize residuals just above next item (dead-space band)
        if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 6 {
            score += 4.0 * (1.0 - progress) ;
        }
