            score -= 40.0 + 60.0 * chain_tightness ;
            let second_post = post_residual - next_item_size ;
            if second_post == 0 { score -= 80.0 ; }
            else if second_post < 10 { score -= 30.0 ; }
            else if second_post < 20 { score -= 12.0 ; }
            else if second_post == next_item_size { score -= 8.0 ; }
            else if second_post < 2 * next_item_size { score -= 0.1 * (2 * next_item_size - second_post) as f64 ; }
            let m = next_item_size . min (item_size) ;
            if second_post >= m { score -= 6.0 ; }
            if second_post >= 2 * m { score -= 4.0 ; }
            if second_post >= 3 * m { score -= 2.0 ; }
            if second_post >= 4 * m { score -= 1.5 ; }
