            score -= 0.15 * chain_val * (1.0 - progress) ;
            if second_post % 5 == 0 && second_post > 0 { score -= 2.0 ; }
            if second_post >= next_item_size {
                let third = second_post - next_item_size ;
                if third == 0 { score -= 10.0 ; }
                else if third < next_item_size / 2 { score -= 3.0 ; }
            }
            if second_post > 0 && second_post < m / 2 { score += 6.0 * (1.0 - progress) ; }
            // new: two-item lookahead chain (item + next both fit twice)
            if item_size + next_item_size <= post_residual && item_size + next_item_size <= bin_capacity {
                let pair = post_residual / (item_size + next_item_size) ;
                score -= 3.0 * pair as f64 * (1.0 - progress) ;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64 ;
            if gap <= 8.0 { score += 25.0 + post_residual as f64 * 0.5 ; }
            else { score += post_residual as f64 * 0.3 ; }
        }
    }
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual . max (0.0)) ;
    }
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual ;
        let crowded = (mean_fill / bin_capacity as f64) . clamp (0.0 , 1.0) ;
        score -= 30.0 * crowded - 10.0 ;
        score += 15.0 * progress ;
        score -= 0.05 * remaining as f64 ;
        if next_item_size > 0 && post_residual >= next_item_size { score += 10.0 ; }
        if fitting_bins_count >= 2 { score += 25.0 ; }
        if item_size as f64 > 0.85 * bin_capacity as f64 { score -= 35.0 ; }
        if item_size as f64 >= 0.95 * bin_capacity as f64 { score -= 60.0 ; }
        if item_size as f64 >= 0.7 * bin_capacity as f64 { score -= 15.0 ; }
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 { score -= 20.0 ; }
        if fitting_bins_count == 0 { score -= 500.0 ; }
        if remaining > 200 && crowded < 0.5 { score += 20.0 * (0.5 - crowded) ; }
        if progress > 0.7 && fitting_bins_count >= 1 { score += 30.0 * (progress - 0.7) / 0.3 ; }
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && progress < 0.6 { score += 6.0 ; }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 { score -= 15.0 ; }
        if item_size as f64 >= 0.8 * bin_capacity as f64 && fitting_bins_count >= 1 && progress < 0.85 { score -= 12.0 ; }
        if post_residual > 0 && next_item_size > 0 && post_residual < (next_item_size / 2) && fitting_bins_count >= 2 && progress < 0.8 { score -= 8.0 ; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity
            && item_size as f64 > 0.5 * bin_capacity as f64 && remaining > 100 { score -= 5.0 ; }
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < adaptive_floor && remaining > 50 {
