        if progress > 0.5 && fitting_bins_count >= 3 && post_residual > 0 && post_residual < 5 { score += 4.0 ; }
        // new: discourage opening a new bin for a near-perfect item when an exact chain exists
        if item_size == post_residual && fitting_bins_count >= 1 { score += 50.0 ; }
        if post_residual == bin_capacity - item_size && fitting_bins_count >= 1 { score += 20.0 ; }
    } else {
        let fill = (bin_residual as f64 / bin_capacity as f64) . clamp (0.0 , 1.0) ;
        score += 4.0 * fill + 3.0 * progress * fill ;
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size ;
            if slack >= 12 { score -= 8.0 ; }
            if slack == 0 { score -= 6.0 ; }
        }
        if post_residual > 0 && post_residual <= 3 { score -= 5.0 ; }
        if progress > 0.75 { score += 5.0 * fill * (progress - 0.75) / 0.25 ; }
        if progress > 0.85 && post_residual == 0 { score -= 10.0 * (progress - 0.85) / 0.15 ; }
        if progress > 0.3 && progress < 0.85 && post_residual > 0 {
            let waste_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64) ;
