    }
    let usable_floor = adaptive_floor ;
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64 ;
        score += 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / usable_floor . max (1) as f64) ;
    }
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0) ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
