pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space avoidance: residuals too small for any item (min size 1, but
    // practically < 10 for classic range) are unusable; penalize harshly.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + fit_ratio);

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize the new-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // keeping loose bins available for larger future items.
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late stream: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but reward perfect match for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: this bin becomes exactly usable by the next item.
            score -= 60.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space relative to lookahead: penalize proportionally.
            let waste = next_item_size as f64 - post_residual as f64;
            score += waste * 0.9;
        } else {
            // post_residual larger than next item: mild preference to keep room.
            score -= 5.0;
        }
    }

    // Compare against mean residual of open bins: avoid bins far below average
    // (they are already fragmented) unless the fit is very tight.
    let pr = post_residual as f64;
    if pr < mean_residual - 15.0 {
        score += (mean_residual - pr) * 0.35;
    } else if pr > mean_residual + 15.0 {
        score -= (pr - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to capacity
    // (poor fit everywhere) or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let bonus = 40.0 * (1.0 - tightness) + 10.0 * progress + 0.5 * pressure;
        score += 55.0 - bonus; // net: good when tightness low / pressure high
    }

    // Small structural bonus for leaving residuals that are "nice" sizes
    // (divisible-friendly chunks), encouraging packable leftovers.
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, weighted non-linearly by stream progress
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear coupling: squared normalized residual with progress modulation
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.7 * progress);

    // Cubic interaction: small residuals are dead space, especially late in stream
    score += (norm_pr * norm_pr * norm_pr) * cap * (1.0 - progress);

