    // Last-chance bonus: if this is the only bin that fits the item,
    // placing here avoids opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // When many bins are open, prefer consolidating into fuller bins
    // (keeps open_bins_count low); early on, allow more spreading
    let spread_pressure = (open_bins_count as f64).ln().max(0.0);
    score += residual_frac * spread_pressure * 12.0;

    // Mean-residual coupling: if this bin's residual is below the mean
    // (i.e., it's fuller than average), reward it — packs dense bins first
    let diff = mean_residual - bin_residual as f64;
    score -= diff * 0.25;

    // Time horizon: late in the stream, be conservative — avoid opening
    // new bins and squeeze everything into existing space
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // New-bin candidate handling: an empty bin should be chosen only when
    // the item is large relative to capacity or nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early on, opening bins is cheap and useful)
        let mut open_cost = 45.0 * (1.0 - 0.5 * progress);
        // Large items justify fresh bins
        open_cost -= fill * 25.0;
        // If few bins fit the item, opening a bin is less costly
        if fitting_bins_count <= 1 {
            open_cost -= 20.0;
        }
        score += open_cost.max(-5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, smoothly warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear penalty on small residuals (dead space), stronger late in stream.
    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0); // peaks near half-full residual
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with quadratic coupling to progress.
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into resulting post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual (prefer balanced bins).
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, slightly penalized early, competitive late.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "usable" for
    // typical small items get rewarded; awkward residues get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual in {0} -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class B: post_residual divisible into nice quarters (25/50/75 style
    // harmonic slots) -> reward for leaving a reusable chunk.
    let quarter = post_residual % 25;
    if quarter == 0 && post_residual > 0 {
        score -= 40.0;
    } else {
        // Penalize distance to nearest quarter harmonic.
        let d = quarter.min(25 - quarter) as f64;
        score += d * 1.5;
    }

    // Class C: post_residual >= 50 (half-bin) is a premium slot; keep it.
    if post_residual >= bin_capacity / 2 {
        score -= 30.0;
    }

    // Class D: tiny dead space (unusable for min-size items) -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic pairing: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let rem2 = post_residual - next_item_size;
            // Reward smoother second-level residual (harmonic of harmonics).
            score -= (rem2 as f64) * 0.4;
            if rem2 % 25 == 0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot follow here: slight penalty proportional to overflow.
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 + 0.5 * (bin_residual.saturating_sub(item_size)) as f64;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.2 * (open_bins_count as f64);
        // But if the item is large relative to capacity, a fresh bin is fine.
        if (item_size as f64) > 0.6 * cap {
            score -= 35.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tight packing), penalize bins far above the mean residual.
    score += ((mean_residual - pr) * 0.15).max(0.0);

    // Stream progression: late in the stream, tighten up (avoid leaving slack).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100, assume >= ~10)
    // and not zero (perfect fit).
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable sliver: heavy penalty.
        score += 45.0;
    } else {
        // Usable gap: mild reward proportional to how well next item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        score += 25.0 + 3.0 * open_bins_count as f64;
        // But if this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // to avoid wasting residual capacity elsewhere.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Slight preference for larger post_residual among usable gaps, already in base term.

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here too: chain placement, big reward scaled by tightness.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            // Bonus if that chained placement would nearly empty the bin.
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            }
        } else {
            // Dead space: next item cannot use the leftover.
            let waste = post_residual as f64;
            // Penalize more when the waste is just below the next item (near miss).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + waste * 0.5;
            } else {
                score += waste * 0.3;
            }
        }
    }

    // Relative-to-mean residual coupling: prefer bins below the mean residual
    // (fill the fullest bins first) unless lookahead favors otherwise.
    let dev = mean_residual - post_residual as f64;
    score += 0.4 * dev;

    // Last-chance bin: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when it enables a clean 2-item chain
    // (item + next item exactly fill a fresh bin) or nothing fits anywhere.
    if bin_residual == bin_capacity {
        let mut base = 150.0; // default cost of opening a new bin
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            // Reward a perfect two-item fresh bin.
            base -= (100 - leftover) as f64 * 1.6;
            if leftover == 0 {
                base -= 120.0;
            }
        }
        if next_item_size == 0 {
            // Last item: fresh bin only if it's a perfect fit.
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        // As the stream progresses, discourage proliferating bins slightly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        base += 40.0 * progress;
        score += base;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (bin_residual as f64 + 1e-9);
    score += 12.0 * fit_ratio * (item_size as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize dead space that the next item cannot use.
            let waste = post_residual.min(next_item_size - 1) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        let best_possible = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let late_game = step_index as f64 / (total_items as f64 + 1e-9);
        score += 25.0 * best_possible;      // penalize new bin if alternatives exist
        score -= 30.0 * pressure;           // reward new bin when nothing fits
        score += 5.0 * (1.0 - late_game);   // slightly discourage new bins early
    }

    // Global state coupling: spread items when mean residual is high, consolidate when low.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.10 * residual_gap;

    // Mild consolidation pressure as the stream progresses.
    let progress = step_index as f64 / (total_items as f64 + 1e-9);
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Prefer using nearly-full bins (small residual) over sparse ones.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post residual (tight packing), with smooth quadratic sharpening.
    let mut score = post + 0.35 * (post / cap) * post;

    // Reward tight fits more strongly as the stream progresses (dead space matters more late).
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 18.0 * tightness * (0.5 + progress);

    // Non-linear coupling: penalize post residual quadratically, amplified by progress
    // and by how many bins are open (fragmentation pressure).
    score += 0.0022 * post * post * (0.4 + 0.6 * progress) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Lookahead: if the next item fits exactly into post_residual, reward strongly;
    // if next item is close to fitting, mild reward; if clearly too big, mild penalty.
    if nxt > 0.0 {
        let gap = post - nxt;
        if gap >= 0.0 {
            let fit_quality = 1.0 - (gap / cap);
            score -= 14.0 * fit_quality * fit_quality * (0.6 + 0.4 * progress);
        } else {
            score += 0.06 * gap.abs() * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0 * (0.6 + 0.4 * progress);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean (an outlier bin),
    // prefer using it to consolidate small residuals.
    let bin_res = bin_residual as f64;
    let dev = (bin_res - mean_residual) / cap;
    score -= 6.0 * dev * dev;

    // New-bin candidate: an empty bin has post_residual = cap - item; make it moderately
    // attractive only when the item is large relative to capacity or fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item / cap;
        score -= 10.0 * large_item * large_item * (0.5 + progress);
        score += 4.0 * (1.0 - large_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual is good, but
    // dead space depends on which "harmonic class" it falls into.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr < 10 {
        score -= 25.0;
    } else if pr < 20 {
        score -= 10.0;
    } else if pr < 35 {
        score -= 3.0;
    } else if pr < 50 {
        score += 5.0;
    } else {
        score += 12.0; // large dead space
    }

    // Modulo structure: residuals that are multiples of common item sizes
    // (or near multiples) are more likely reusable.
    let mod10 = pr % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 <= 2 || mod10 >= 8 {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: does next item fit in post residual?
    if next_item_size > 0 && next_item_size <= pr {
        // next item fits: reward proportionally to how snugly
        let snug = 1.0 - (pr - next_item_size) as f64 / cap;
        score -= 8.0 * snug;
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here; penalize less if residual is tiny anyway
        score += (next_item_size - pr) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many options: prefer tightest fit, mild penalty for slack
        score += 2.0;
    }

    // Harmonic threshold on integer division: bins whose residual class
    // (residual / 25) is low are more "complete".
    let quarter = bin_residual / 25;
    score -= quarter as f64 * 3.0;

    // Fraction of capacity used by this placement
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 10.0;

    // Stream progression: late in stream, be more aggressive about filling
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's a good compaction target.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.1;
    } else {
        score += (-dev) * 0.05;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely
    // necessary (few fitting bins or huge item).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 30.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // reserving fresh space for big follow-up
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range)
    // are worthless -> heavy penalty so we prefer bins where leftover stays usable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Waste that can't serve the next item: mild penalty scaled by waste size.
        score += (post_residual as f64).min(30.0) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin;
    // make the new-bin candidate less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is OK if the item is huge and would leave a tiny gap anyway.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Mild reward for filling already-open bins, scaled by how full they are.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        // Prefer bins tighter than the mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 200.0;
    }

    // 2-step lookahead: bonus if next item exactly fills the new residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score -= 50.0; // small dead space acceptable if next item can't use it anyway
        }
    }

    // Penalize large residual relative to mean residual (wasted space elsewhere)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 - mean_residual) * 0.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless existing bins would leave bad residuals
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin still supports the next item well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual more than linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize wasted remainder.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of existing bins.
    if bin_residual == bin_capacity {
        // Prefer opening new bins only when few bins fit or existing residuals are large.
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else {
            1.0
        };
        score += 8.0 * pressure;
        // Penalize new bins more as stream progresses (lock in consolidation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual across open bins is big, avoid opening new bins.
        score += 0.25 * mean_residual;
        // If next item is small, an existing bin likely serves it too.
        if next_item_size > 0 && next_item_size <= 40 {
            score += 6.0;
        }
    } else {
        // Slight preference for bins with smaller residuals among open bins (best-fit flavor).
        score -= 0.05 * (bin_capacity - bin_residual) as f64;
    }

    // Late-stream consolidation: favor filling existing bins harder near the end.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * t * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty proportional to number of open bins to encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;

    // Smooth non-linear decay of residual value over the stream:
    // early on, tight fits matter more (waste penalized quadratically),
    // late in the stream, residual becomes cheaper to leave behind.
    let tightness_weight = 1.0 + 2.0 * (1.0 - progress) * (1.0 - progress);
    score *= tightness_weight;

    // Non-linear coupling between post_residual and mean residual:
    // penalize leaving residuals far above the fleet mean (dead space),
    // reward residuals near the mean (likely reusable later).
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let diff = post_residual as f64 - mr;
    let coupling = 0.05 * diff * diff / (bin_capacity as f64);
    score += coupling * (0.5 + p2);

    // Smooth penalty when this bin is the last fitting option:
    // strongly favor using it rather than opening a new bin.
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 - p2 * 0.5);

    // Interaction: perfect fits (post_residual small) get a smooth
    // super-linear reward, scaled by how many alternatives exist.
    let pr = post_residual as f64;
    let fit_reward = (pr * pr) / (bin_capacity as f64);
    score += fit_reward * (1.0 + (fitting_bins_count as f64).ln().max(0.0));

    // Lookahead: mildly reward leaving room for the next item,
    // with smooth saturation via ratio of post_residual to next item.
    if next_item_size > 0 {
        let ratio = (post_residual as f64) / (next_item_size as f64);
        let s = ratio / (1.0 + ratio); // smooth saturating term in [0,1)
        score -= 8.0 * s * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely
    // attractive (smooth function of progress and open bin count).
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 10.0 * crowd * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic octile classes

    // Reward placements whose post-residual falls into a "useful" harmonic class
    // (large residuals can host typical small items; tiny residuals are near-perfect fits).
    match class {
        0 => score -= 25.0,             // near-perfect fit: minimal dead space
        1 => score -= 10.0,             // small but usable residual
        2 => score -= 4.0,              // moderate residual
        3 => score -= 0.0,
        4 => score += 6.0,              // half-ish bin: awkward zone
        5 => score += 2.0,
        6 => score -= 3.0,              // large residual, still flexible
        _ => score -= 5.0,              // nearly empty bin placement
    }

    // Modulo arithmetic on post_residual: residuals congruent to small values
    // mod common item sizes are more likely to be exactly filled later.
    let mut congruence_bonus = 0.0;
    for m in [10u32, 20, 25, 50] {
        let r = post_residual % m;
        if r == 0 {
            congruence_bonus += 4.0;
        } else if r <= 5 {
            congruence_bonus += 2.0;
        }
    }
    score -= congruence_bonus;

    // Integer-division threshold: post_residual / 2 must still host a typical item.
    if post_residual / 2 >= 20 {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 4.0; // dead space too small to split usefully
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match is golden
            if post_residual == next_item_size {
                score -= 30.0;
            } else {
                score -= 8.0;
                // penalize if the leftover after next item is a dead class again
                let next_post = post_residual - next_item_size;
                if next_post < 10 && next_post > 0 {
                    score += 5.0;
                }
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bins are flexible; only prefer them when
    // the best possible placement in an open bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 15.0;
        // cheap to open early in the stream when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * (1.0 - progress);
        // opening a new bin is attractive when existing residuals are fragmented
        if mean_residual > 0.0 && mean_residual < (bin_capacity as f64) * 0.3 {
            score -= 8.0;
        }
        // if current item is large, a fresh bin guarantees a clean harmonic class
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += open_bins_count as f64 * 0.15;

    // Slight preference for tighter existing bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Non-linear penalty on small residuals (dead space), stronger late in stream.
    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits with quadratic coupling to progress.
    score -= 8.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0 + 15.0 * progress;
    }

    // Two-step lookahead: chain placement reward scaled by tightness.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let chain_tightness = nxt / (pr + 1.0);
            score -= 20.0 + 50.0 * chain_tightness * (0.5 + 0.5 * progress);
            let second_post = pr - nxt;
            if second_post < 10.0 {
                score -= 25.0 * (0.5 + 0.5 * progress);
            }
            let slack = second_post / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            let gap = nxt - pr;
            if gap <= 10.0 {
                // Near miss: dead space that almost hosted the next item.
                score += 20.0 + 0.3 * pr;
            } else {
                score += 5.0 * gap / cap;
            }
        }
    }

    // Prefer filling the fullest bins: deviation from mean residual.
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: costly by default, but attractive when it enables
    // a clean two-item chain (item + next item fill a fresh bin).
    if bin_residual == bin_capacity {
        let mut base = 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 1.6;
            if leftover == 0 {
                base -= 120.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    score
}

