                base -= 140.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        // Opening a new bin is more tolerable when many bins are already open
        // and the stream is late: consolidation pressure has done its job.
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.06 * open_bins_count as f64 * pr_norm;

    // Bonus for bins whose residual exactly matches the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Extra: reward bins whose residual is an exact multiple split for the
    // next item, leaving a perfectly packable remainder.
    if next_item_size > 0 && post_residual > next_item_size {
        let rem = post_residual - next_item_size;
        if rem == item_size && item_size > 0 {
            score -= 35.0;
        }
    }

    // Penalize bins that can only host the current item with large leftover
    // while another bin could host item + next item (avoid fragmentation).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 * (next_item_size - post_residual) as f64 / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

