    // Penalize leaving large dead space relative to typical future demand
    let dead_ratio = post_residual as f64 / (bin_capacity as f64 + 1.0);
    if dead_ratio > 0.25 && post_residual >= next_item_size {
        score += (dead_ratio - 0.25) * 80.0;
    }

    // Mild bonus for tight fits: residual close to item size
    let tightness = (post_residual as i64 - item_size as i64).unsigned_abs() as f64;
    if tightness <= 5.0 {
        score -= 15.0;
    }

    // Prefer new bin when few fitting bins and current residual is a poor fit
    if bin_residual == bin_capacity {
        // new-bin candidate: reward opening fresh bin when existing fits are loose
        if fitting_bins_count > 1 {
            let best_loose = post_residual as f64 > next_item_size as f64 * 2.0;
