}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead chain logic (k=2): reward bins whose post-residual serves the next item,
    // especially when the second-level leftover is also tight.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            }
        } else {
            let waste = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + waste * 0.5;
            } else {
                score += waste * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is OK if the item is huge and would leave a tiny gap anyway.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
        // Never open a new bin when the lookahead item would fit the fresh bin but
        // an existing bin already serves the current item well.
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Reward filling already-open bins, scaled by how full they are.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        // Prefer bins tighter than the mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
        // Extra reward for near-exact fits relative to the item.
        if post_residual < item_size / 4 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
