    }

    // New-bin candidate: baseline high enough that only genuinely bad fits
    // among open bins justify opening a new one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 90.0 + 0.5 * mean_residual - 15.0 * (1.0 - progress) - 1.0 * open_bins_count as f64;
        // If some open bin leaves a near-perfect fit, opening fresh is bad.
        if frac < 0.05 {
            score += 20.0;
        }
    }

    // Best-fit bias toward bins tighter than the mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

