            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post > 0 && second_post < 10 {
                score -= 30.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is fine for huge items leaving tiny gaps.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size (1..10)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer tight fits: reward small post_residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 15.0;

    // Open-bin pressure: discourage spreading across many bins
    // unless the fit is excellent; penalize lightly per open bin.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin
    // fits well (large dead-space risk) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - progress * 20.0;
        if post_residual < 20 {
            // opening a fresh bin for a big item leaves a large residual,
            // which is fine early but wasteful late.
            score -= (20 - post_residual) as f64 * 1.5;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post_residual, reward; if it cannot fit, penalize the dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // Slight alignment with mean residual: prefer bins below the mean
    // (smaller residuals) to consolidate fullness.
    score += (mean_residual - post_residual as f64) * -0.3;

    score
}

