    }

    // Dead-space avoidance: residuals too small for typical items are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Lookahead (k=2): reward chains that leave room for the next item,
    // with extra reward when the second leftover is also dead-space-free.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
