            if gap <= 10.0 {
                score += 25.0 + waste * 0.5;
            } else {
                score += waste * 0.3;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening yet another bin when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is OK if the item is huge and would leave a tiny gap anyway.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Reward filling already-open bins, scaled by how full they are.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        // Prefer bins tighter than the mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
