        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to hold a plausible item (<=10 min item size).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item can use this bin's post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to leftover waste
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly avoid opening a new bin
    // unless the fit would be terrible (huge post_residual waste).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
        if post_residual < 10 {
            score -= 10.0; // perfect-ish fit as last resort
        }
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current open bins are nearly full
        // or the fit in open bins would leave large unusable residue.
        let tight_open = (mean_residual / bin_capacity as f64) < 0.15 * (item_size as f64);
        if open_bins_count > 0 && !tight_open && post_residual >= 10 {
            score += 40.0; // discourage wasting a fresh bin
        } else if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        } else {
            score -= 15.0; // all bins nearly full: fresh bin is good
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into bins with below-average residual (denser bins).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64) - mean_residual;
        score += 0.3 * rel; // prefer bins with less residual than average
    }

    // Time horizon: early in stream, be slightly more exploratory (favor new bins
    // for large items to preserve flexibility); late in stream, consolidate hard.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if progress < 0.3 && item_size > 60 {
        score -= 5.0;
    }
    score += 10.0 * progress * (post_residual as f64 / 100.0);

    // Mild preference for larger item into larger residual bins to avoid fragmentation.
    score += 0.1 * ((bin_capacity - bin_residual) as f64) * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1200.0;
    }

    // Non-linear penalty on small residuals (dead space), stronger late in stream.
    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits with quadratic coupling to progress.
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 110.0 + 25.0 * progress;
    }

    // Two-step lookahead: chain placement reward scaled by tightness.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let chain_tightness = nxt / (pr + 1.0);
            score -= 35.0 + 70.0 * chain_tightness * (0.5 + 0.5 * progress);
            let second_post = pr - nxt;
            if second_post == 0.0 {
                score -= 200.0;
            } else if second_post < 10.0 {
                score -= 35.0 * (0.5 + 0.5 * progress);
            } else if second_post < 25.0 {
                score -= 12.0;
            }
            let slack = second_post / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            let gap = nxt - pr;
            if gap <= 10.0 {
                score += 25.0 + 0.5 * pr;
            } else {
                score += 6.0 * gap / cap + 0.2 * pr;
            }
        }
    }

    // Prefer filling the fullest bins: deviation from mean residual.
    score += 0.35 * (mean_residual - pr);

    // New-bin candidate: costly by default, but attractive when it enables
    // a clean two-item chain (item + next item fill a fresh bin).
    if bin_residual == bin_capacity {
        let mut base = 160.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 2.0;
            if leftover == 0 {
                base -= 200.0;
            } else if leftover <= 5 {
                base -= 60.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.06 * open_bins_count as f64 * pr_norm;

    // Bonus for bins whose residual exactly matches the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel: penalize residuals too small to host the
    // next item; peak penalty at ~half item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 20.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
        }
    }

    // Reward bins whose residual after placement stays above a usable floor.
    if post_residual >= 25 && post_residual < bin_capacity {
        score -= 8.0 * (0.4 + 0.6 * progress);
    }

    // Strong consolidation pressure when many bins are open.
    if open_bins_count > 6 {
        score += 0.9 * pr_norm * (open_bins_count as f64).min(20.0);
    }

    // Near-perfect chain: residual after placement fits next item with tiny
    // slack -> deep reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 3 {
            score -= 45.0 + 30.0 * progress;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1200.0 ; }
