            score -= 40.0 + 60.0 * chain_tightness ;
            let second_post = post_residual - next_item_size ;
            if second_post < 12 { score -= 30.0 ; }
            else if second_post >= next_item_size { score -= 10.0 ; }
        } else {
            let waste = post_residual as f64 ;
            let gap = (next_item_size - post_residual) as f64 ;
            if gap <= 10.0 { score += 25.0 + waste * 0.5 ; }
            else { score += waste * 0.3 + gap * 0.2 ; }
        }
    }
    // penalize leaving large residuals when few bins can still host the next item
    if fitting_bins_count <= 1 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 ;
    }
    // mild pressure against opening new bins late in the stream when a decent fit exists
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual >= item_size {
        score += 8.0 + (post_residual as f64) * 0.05 ;
    }
    // reward near-perfect compaction relative to mean residual
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score -= 5.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Base: prefer tight fits (low post_residual), amplified by progress.
    let mut score = pr * (1.0 + progress * progress * 2.0);

    // Cubic dead-space penalty: residuals that are unusably small matter more later.
    score += (pr / cap).powi(3) * 40.0 * (0.5 + progress);

    // Reward filling the bin deeply (item_size relative to capacity), coupled with progress.
    score -= (item_size as f64 / cap).powi(2) * 15.0 * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor leaving post_residual that can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)));
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - pr / cap);
    }

    // Penalize spreading across many open bins relative to mean residual.
    score += ((open_bins_count as f64) / (1.0 + mean_residual / cap)) * 0.5;

    // New-bin candidate: mildly penalized so it's chosen only for poor fits,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
