            if second_post < 10 { score -= 30.0 ; }
            // deep lookahead: residual left after the next item can still host small items
            if second_post > 0 && second_post < item_size.min(15) { score -= 12.0 ; }
        } else {
            let waste = post_residual as f64 ;
