    if bin_residual > item_size && bin_residual < item_size + 6 {
        score -= 20.0 ; // near-perfect snug fit bonus
    }
    // when many bins can host, prefer the tightest; when only one, avoid over-penalizing
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - item_size as f64) * 0.15 ;
    }
    // new-bin candidate: discourage opening a bin unless no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 } ;
        let mean_gap = mean_residual - item_size as f64 ;
        let open_bonus = if mean_gap.abs() < 8.0 || scarcity > 0.0 { -50.0 } else { 120.0 + open_bins_count as f64 * 2.0 } ;
        score += open_bonus ;
    }
    score
