pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold any item are wasted.
    if post_residual < 10 {
        score -= 15.0; // near-perfect packing is great
    } else if post_residual < 20 {
        score += 12.0; // small but non-zero dead space is the worst outcome
    } else if post_residual <= 30 {
        score += 4.0; // moderate dead space, still potentially usable
    }

    // Exact fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class logic: classify residual by capacity fractions (integer division).
    // Residuals in (0, C/4) are nearly dead; (C/4, C/2) are awkward; large residuals are flexible.
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    if post_residual > quarter && post_residual <= half {
        score -= 3.0; // awkward zone but flexible enough
    } else if post_residual > half {
        score -= 6.0; // large residual keeps flexibility
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual - next_item_size < 10 {
            score -= 18.0; // chains two items nearly perfectly
        } else {
            score -= 6.0; // next item still fits afterwards
        }
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit here before this placement but won't after: penalize.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mildly prefer tighter fills via post_residual (already handled),
        // small penalty to spread load when bins are plentiful.
        score += 2.0;
    }

    // Prefer using bins whose residual is close to the item (tight fit) via relative slack.
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += slack_ratio * 5.0;

    // Mean-residual coupling: if the average residual across open bins is large, opening
    // new bins is cheap-ish, so be pickier about poor fits (raise scores of bad fits).
    if mean_residual > half as f64 && post_residual > quarter {
        score += 5.0;
    }

    // Stream progression: late in the stream, avoid opening new bins; favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early in stream
        // or when no open bin fits well.
        let new_bin_penalty = 10.0 + 30.0 * progress;
        score += new_bin_penalty;
        if open_bins_count == 0 {
