    } else if post_residual <= 35 {
        score += 8.0;
    } else if post_residual <= 50 {
        score -= 4.0;
    } else {
        score -= 10.0;
    }

    // Harmonic modulo nudges.
    let m = post_residual % 10;
    if post_residual > 0 && m == 0 {
        score -= 6.0;
    } else if m == 1 || m == 9 {
        score += 3.0;
    } else if m == 2 || m == 8 {
        score += 2.0;
    }

    // Lookahead chaining (borrowed strength from best-known): reward bins whose
    // post_residual can host the next item tightly, penalize unusable leftovers.
    if next_item_size > 0 {
