    }

    // Last-chance: sole fitting open bin is precious.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate baseline: neutral-to-slightly-negative, so it only wins
    // when every open bin would leave bad leftovers.
    if bin_residual == bin_capacity {
