        if tight > 0.85 {
            score -= 20.0 * (tight - 0.85) * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer tight fits, weighted more strongly late in the stream
    let tightness = 1.0 - pr_norm;
    let progress_weight = 0.5 + 4.0 * progress * progress;
    score -= tightness * progress_weight * 10.0;

    // Cubic penalty on wasted residual, amplified with progress (dead space becomes costly late)
    score += pr_norm * pr_norm * pr_norm * (2.0 + 6.0 * progress) * 10.0;

    // Interaction: small post-residual combined with large next item is valuable (chains well)
    if next_item_size > 0 {
        let nxt = (next_item_size as f64).clamp(1.0, 100.0);
        let chain_fit = if pr >= nxt as u32 { 1.0 } else { 0.0 };
        let chain_quality = 1.0 - ((pr - nxt) / cap).clamp(0.0, 1.0);
        score -= chain_fit * chain_quality * (3.0 + 5.0 * progress) * smooth(fitting_bins_count as f64);
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty when this bin is far below mean residual (keeps residual distribution compact)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0;

    // Mild pressure against proliferating bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    // New-bin candidate: smooth repulsion so it only wins when open bins are genuinely bad fits
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

// Smooth saturating helper (logistic-like), avoids piecewise constants
fn smooth(x: f64) -> f64 {
    1.0 - (-x.abs()).exp()
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr * (1.0 + 0.5 * progress);

    if post_residual == 0 {
        score -= 1000.0;
    }

    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 20.0 * progress;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let chain_tightness = nxt / (pr + 1.0);
            score -= 25.0 + 60.0 * chain_tightness * (0.5 + 0.5 * progress);
            let second_post = pr - nxt;
            if second_post < 10.0 {
                score -= 30.0 * (0.5 + 0.5 * progress);
            } else if second_post < 25.0 {
                score -= 10.0;
            }
            let slack = second_post / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            let gap = nxt - pr;
            if gap <= 10.0 {
                score += 22.0 + 0.4 * pr;
            } else {
                score += 6.0 * gap / cap;
            }
        }
    }

    score += 0.35 * (mean_residual - pr);

    if bin_residual == bin_capacity {
        let mut base = 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 1.8;
            if leftover == 0 {
                base -= 140.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        // New mutation: new bins are more acceptable early when few bins exist.
        if open_bins_count < 4 && progress < 0.2 {
            base -= 40.0;
        }
        score += base;
    }

    score += 0.06 * open_bins_count as f64 * pr_norm;

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel for residuals too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 18.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
        }
    }

    // Reward keeping residuals above a usable floor.
    if post_residual >= 25 && post_residual < bin_capacity {
        score -= 8.0 * (0.4 + 0.6 * progress);
    }

    if open_bins_count > 6 {
        score += 0.9 * pr_norm * (open_bins_count as f64).min(20.0);
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 3 {
            score -= 35.0 + 25.0 * progress;
        }
    }

    // NEW (gen 8): two-item lookahead on triple slack — after placing item and
    // next item, penalize leftovers too small for typical follow-ups, and
    // reward three-item chains when the residual can host next twice.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        let third_slack = post_residual - 2 * next_item_size;
        if third_slack <= 5 {
            score -= 40.0 * (0.5 + 0.5 * progress);
        }
    }

    // NEW (gen 8): exponential dead-space penalty for residuals in the
    // awkward zone (1..=15) that can host only tiny items.
    if post_residual >= 1 && post_residual <= 15 {
        score += (16.0 - pr) * (1.2 + 1.2 * progress);
    }

    // NEW (gen 8): stronger consolidation when many bins are open and the fit
    // is tight — amplified best-heuristic-style tightness reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let t = next_item_size as f64 / (pr + 1.0);
        score -= 15.0 * t * t * (open_bins_count as f64).min(15.0) / 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is gold: near-dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Lookahead (k=2): reward bins that can also serve the next item,
    // scaled by how tightly the next item fills the resulting gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post > 0 && second_post < 10 {
                score -= 30.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += (post_residual as f64).min(30.0) * 0.3;
            }
        }
    }

    // Last-chance bin: only fitting bin -> prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening yet another bin as bins accumulate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is fine if the item nearly fills it anyway.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Reward filling already-open bins, scaled by fill ratio.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        // Prefer bins tighter than the mean residual (good fits).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction bands. Residuals in "harmonic" bands (small multiples
    // of common item sizes) are more reusable; odd residuals are penalized.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap_f;

    // Harmonic band index via integer division on post_residual:
    // 0: (0,10], 1: (10,20], 2: (20,30], 3: (30,50], 4: (50,100]
    let band = match post_residual {
        0 => 0u32,
        1..=10 => 1,
        11..=20 => 2,
        21..=30 => 3,
        31..=50 => 4,
        _ => 5,
    };
    // Reward tight fits (small band), punish large dead space mildly superlinearly.
    score += band as f64 * 2.0;
    score += frac * frac * 12.0;

    // Perfect-fit bonus: post_residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic: residuals that are multiples of small harmonics (5, 10)
    // are likelier to be filled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 4.0;
        } else {
            score += 3.0; // awkward residual
        }
    }

    // Lookahead coupling: reward if next item can exactly fill post_residual,
    // penalize if next item would be blocked by this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to tightness
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap_f);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current residuals are fragmented (high mean residual spread) or many bins.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // if the item is large relative to capacity, a fresh bin is fine
        if (item_size as f64) > 0.7 * cap_f {
            score -= 20.0;
        }
        // if few fitting bins and existing bins are fragmented, new bin is OK
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // late in the stream, avoid bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for bins below the mean residual (keeps balance,
    // preserves larger holes for larger future items).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Early stream: be greedy about tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64).min(20.0) * 0.5;

    score
}

