    // practically < 10 for classic range) are unusable; penalize harshly.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + fit_ratio);

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize the new-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 4.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // keeping loose bins available for larger future items.
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late stream: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
