    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel: penalize residuals smaller than the next
    // item that cannot host it; peak penalty at ~half of next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 20.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
