    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small nonzero post_residual is wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving enough room for the next item, scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to overshoot.
        let over = (next_item_size - post_residual) as f64;
        score += 5.0 + over * 0.1;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead suggests
    // a large future item better served by fresh space.
    if bin_residual == bin_capacity {
        let fresh_bonus = if next_item_size > 0 && next_item_size > bin_residual - item_size {
            10.0
        } else {
            0.0
        };
        score += 25.0 - fresh_bonus;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.2 * progress;

