}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress);

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Non-linear penalty on small residuals (dead space), stronger late in stream.
    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits with quadratic coupling to progress.
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 20.0 * progress;
    }

    // Two-step lookahead: chain placement reward scaled by tightness.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let chain_tightness = nxt / (pr + 1.0);
            score -= 25.0 + 60.0 * chain_tightness * (0.5 + 0.5 * progress);
            let second_post = pr - nxt;
            if second_post < 10.0 {
                score -= 30.0 * (0.5 + 0.5 * progress);
            } else if second_post < 25.0 {
                score -= 10.0;
            }
            let slack = second_post / cap;
            score -= 5.0 * (1.0 - slack * slack);
        } else {
            let gap = nxt - pr;
            if gap <= 10.0 {
                // Near miss: dead space that almost hosted the next item.
                score += 22.0 + 0.4 * pr;
            } else {
                score += 6.0 * gap / cap;
            }
        }
    }

    // Prefer filling the fullest bins: deviation from mean residual.
    score += 0.35 * (mean_residual - pr);

    // New-bin candidate: costly by default, but attractive when it enables
    // a clean two-item chain (item + next item fill a fresh bin).
    if bin_residual == bin_capacity {
        let mut base = 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 1.8;
            if leftover == 0 {
                base -= 140.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.06 * open_bins_count as f64 * pr_norm;

    // Bonus for bins whose residual exactly matches the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel: penalize residuals too small to host the
    // next item; peak penalty at ~half of it, stronger late in stream.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 18.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
        }
    }

    // Reward bins whose residual after placement stays above a usable floor.
    if post_residual >= 25 && post_residual < bin_capacity {
        score -= 8.0 * (0.4 + 0.6 * progress);
    }

    // Strong consolidation pressure when many bins are open.
    if open_bins_count > 6 {
        score += 0.9 * pr_norm * (open_bins_count as f64).min(20.0);
    }

    // Near-perfect chain: residual after placement fits next item with tiny slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 3 {
            score -= 35.0 + 25.0 * progress;
        }
    }

    // --- GEN 10 MUTATIONS: tighter lookahead-residual coupling ---

    // Cubic tightness kernel: reward placements that leave near-zero slack
    // relative to typical future demand, sharper than the quadratic base.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = (post_residual - next_item_size) as f64;
        let tight = 1.0 - (slack2 / (next_item_size as f64 + 1.0)).min(1.0);
        score -= 20.0 * tight * tight * tight * (0.5 + 0.5 * progress);
    }

    // Penalize residuals in the "awkward zone": too big to waste, too small to
    // fit the mean of remaining demand; drives selection toward best-fit bins.
    if pr > 0.0 && pr < mean_residual.max(1.0) {
        let r = pr / mean_residual.max(1.0);
        score += 10.0 * (1.0 - r) * (0.3 + 0.7 * progress);
    }

