    // remainder, deepen the chain reward proportionally to usable slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 >= 10 && slack2 <= 40 {
            score -= 12.0 * (1.0 - slack2 as f64 / 40.0);
        }
    }

    // Late-stream waste aversion: large leftover residuals are heavily punished
    // near the end, pushing items into the tightest available bins.
    if progress > 0.6 && post_residual > 0 {
        score += 0.25 * pr * (progress - 0.6);
    }

    // New-bin suppression refinement: when a decent existing fit exists, make
    // opening a new bin more expensive unless the chain is perfect.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 && !(next_item_size > 0 && item_size + next_item_size == bin_capacity) {
            score += 60.0;
        }
    }

    score
}

