pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus: strongly reward leaving (near) zero space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward post_residual that exactly (or closely) matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 300.0;
        } else if diff <= 5 {
            score -= 100.0;
        } else if (post_residual as i64) < (next_item_size as i64) {
            // Next item cannot fit here: mild penalty scaled by wasted gap.
            score += diff as f64 * 0.5;
        } else {
            score += diff as f64 * 0.2;
        }
    }

    // Compare against mean residual: penalize consuming a large-residual bin too eagerly
    // if mean residual is high (many bins have slack); reward when mean residual is low.
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual <= 20 {
            score -= 60.0;
        }
    }

    // New-bin candidate: make empty bin attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Default: new bin is a fallback — add penalty so it's chosen only when
        // open bins have bad fits.
        score += 120.0;
        // If lookahead suggests next item pairs with a fresh full bin, soften penalty.
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64).abs() <= 5 {
            score -= 50.0;
        }
        // Late in the stream, opening new bins is riskier (stranded residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // Many open bins: prefer consolidating into them.
