    // Prefer filling the fullest bins: deviation from mean residual.
    score += 0.35 * (mean_residual - pr);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mut base = 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 1.8;
            if leftover == 0 {
                base -= 140.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        // New bin is more tolerable when no open bin can host a decent chain.
        if fitting_bins_count == 0 {
            base -= 25.0;
        }
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.06 * open_bins_count as f64 * pr_norm;

    // Perfect chain: residual after placement exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel: penalize residuals too small for next item
    // but wasteful; peak penalty near half the next item's size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 18.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
        }
    }

    // Reward bins whose post residual stays above a usable floor for mid-sized items.
    if post_residual >= 25 && post_residual < bin_capacity {
        score -= 8.0 * (0.4 + 0.6 * progress);
    }

    // Consolidation pressure when many bins are open: prefer smallest residual.
    if open_bins_count > 6 {
        score += 0.9 * pr_norm * (open_bins_count as f64).min(20.0);
    }

    // Near-perfect chain: residual after placement fits next item with tiny slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 3 {
            score -= 35.0 + 25.0 * progress;
        }
    }

    // --- NEW MUTATIONS (gen 12): combine residual fitting with lookahead ---
    // Best-fit bias: strongly favor the bin whose residual most closely matches
    // the item, independent of absolute residual magnitude.
    let fit_gap = (bin_residual - item_size) as f64;
    score -= 20.0 / (1.0 + fit_gap * 0.08);

    // Lookahead-aware waste scoring: penalize post-residuals that neither fit
    // the next item nor are near zero — these are likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 14.0 * (1.0 - pr / next_item_size as f64);
    }

    // Encourage leaving residuals that can host a broad range of future items:
    // residual near mean_residual implies good reusability.
    if post_residual > 0 {
        let reuse = 1.0 - ((pr - mean_residual).abs() / cap).min(1.0);
        score -= 6.0 * reuse * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic waste penalty, softly damped by stream progress
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Non-linear coupling: post_residual vs progress (later in stream -> penalize waste more)
    score += 40.0 * norm_post * norm_post * progress * (1.0 - progress * 0.5);

    // Interaction with mean residual: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 25.0 * dev * dev * (1.0 + progress);

    // Lookahead coupling: reward if next item can use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let fit_quality = (post_residual - next_item_size) as f64 / cap;
            score -= 30.0 * (1.0 - fit_quality) * (1.0 - progress * 0.6);
        } else {
            // post residual likely dead space relative to next item
            score += 10.0 * (1.0 - post / nx) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 + progress);
    }

    // New-bin candidate handling: only attractive early or when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = cap * (1.2 + 0.8 * progress) + 20.0 * (open_bins_count as f64).ln().max(0.0);
        // allow new bin if all fits are terrible
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (zero waste)
    if post_residual == 0 {
        score -= 1200.0;
    }

    // New-bin candidate: penalize unless residual pressure is high
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_r = mean_residual.max(1.0);
        // open a fresh bin only when open bins are fragmented (large mean residual, few fits)
        score += 300.0 - 150.0 * scarcity - (mean_r / bin_capacity as f64) * 120.0;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead chain: reward bins that can also host the next item
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 45.0 + 70.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            // bonus if remaining space stays small but usable
            if second_post < 12 {
                score -= 35.0;
            } else if second_post > 40 {
                // large leftover after chain: mild penalty to avoid squandering
                score += (second_post as f64) * 0.15;
            }
        } else {
            let waste = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 12.0 {
                // near-miss for next item: penalize wasting this residual
                score += 28.0 + waste * 0.55;
            } else {
                score += waste * 0.3;
            }
        }
    }

    // slight preference for bins with small residual overall (compactness)
    score += (bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Penalize residuals that fall into "useless" harmonic classes:
    // small but nonzero slivers (1..=eighth) are nearly dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if (pr) < eighth {
        score += 12.0;
    } else if pr < quarter {
        score -= 4.0; // still usable for medium items
    } else {
        score -= 8.0; // large residual stays attractive
    }

    // Perfect fit reward: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly reward this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // residual that can host next item: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // post_residual too small for next item: penalize dead-space creation
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are bad. Give it a moderate baseline score keyed to its class.
    if bin_residual == bin_capacity {
        // Empty bin: score = capacity minus a discount that grows as the stream
        // progresses (more willing to open bins early, keep consolidating late).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = cap - 20.0 * (1.0 - progress);
        // If next item is large, an empty bin preserves flexibility.
        if next_item_size > item_size {
            score -= 5.0;
        }
        // Late in stream, strongly prefer existing bins.
        if progress > 0.7 {
            score += 10.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins whose residual is near the mean (balanced packing).
    score += 0.1 * ((pr - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
