pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot fit even the smallest
    // plausible item are pure waste; penalize them heavily.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Gaps too small for the next item (when known) are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // Open-bins pressure: with many open bins, discourage spreading onto
    // fresh space; with few open bins, allow slight preference for tight fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate handling: an empty bin is only attractive when the
    // item fits poorly everywhere else, or the stream is early and we can
    // amortize the bin. Otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 1.15;
        if poor_fit_elsewhere || fitting_bins_count == 0 {
            score -= 30.0; // opening a new bin is justified
        } else {
            score += 35.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        }
    }

    // Reward placing large items into large-residual bins (big-in-big).
    if item_size >= 60 && bin_residual >= 70 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is gold: heavy reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Lookahead chain (k=2): reward bins whose leftover can tightly host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post > 0 && second_post < 10 {
                score -= 30.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: sole fitting bin strongly preferred over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling with open-bin pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is fine if the item nearly fills it.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Reward filling already-open bins, scaled by fullness.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 8.0;
        // Prefer bins tighter than the mean residual.
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space avoidance: residuals too small to be useful.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + fit_ratio);

    // Lookahead chain: if next item fits into post_residual, reward heavily,
    // scaled by how much of the residual the next item consumes.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Open-bin pressure: penalize the new-bin candidate when open bins exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer tighter bins, keeping loose bins
    // available for larger future items.
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Late stream: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: item + next item perfectly fills this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward tightness of the two-step fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - slack * 0.5;
        } else {
            // Next item cannot follow here: penalize dead space, worse when tiny.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
            if post_residual < 10 {
                score += 30.0; // near-unusable sliver
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 { score -= 1000.0 ; }
    // brand-new empty bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let tight_supply = fitting_bins_count <= 1 ;
        let big_next = next_item_size as f64 > mean_residual * 0.8 ;
        if tight_supply || big_next { score -= 250.0 ; } else { score += 120.0 ; }
        return score ;
    }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0) ;
            score -= 40.0 + 60.0 * chain_tightness ;
            let second_post = post_residual - next_item_size ;
            if second_post < 10 { score -= 30.0 ; }
            else if second_post < 20 { score -= 12.0 ; }
        } else {
            let waste = post_residual as f64 ;
            let gap = (next_item_size - post_residual) as f64 ;
            if gap <= 10.0 { score += 25.0 + waste * 0.5 ; }
            else { score += waste * 0.3 + (gap - 10.0) * 0.15 ; }
        }
    }
    // prefer bins whose residual is an awkward size unlikely to fit typical items
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 8.0 ;
    }
    // slight penalty for spreading across many open bins when fits are plentiful
    if fitting_bins_count > 3 { score += 3.0 ; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large post_residual dead space more when many bins are open.
    let waste_penalty = (post_residual as f64).powf(1.5) / 100.0;
    score += waste_penalty * (1.0 + open_bins_count as f64 / 10.0);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 8.0;
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in stream, be pickier about waste (long future to regret it);
    // late in stream, just close bins out efficiently.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // Global state coupling: if mean residual is high, prefer using bins with
    // residual below mean (compact them), leaving big residual bins for big items.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // New-bin candidate: only attractive when item is large and no good fit exists,
    // or when open bins all have large residuals that would be badly fragmented.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64).powi(2) * 40.0;
        score -= large_item_bonus;
        score += 10.0 * (fitting_bins_count as f64).min(5.0);
        // Early on, opening bins is cheap; later, prefer filling existing ones.
        score += 15.0 * progress;
        // If a future item is small, a fresh bin wastes capacity.
        if next_item_size > 0 && next_item_size < 20 {
            score += 6.0;
        }
    }

    // Mild bonus for bins whose residual is close to item size (perfect-ish fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 5.0 * (-gap / 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
