    }

    // Strong lookahead chaining: reward bins whose leftover serves the next item,
    // with extra reward when the second leftover would also be tiny.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            } else if second_post % 10 == 0 {
                score -= 10.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // A leftover that just misses the next item is nearly useless.
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline tuned against stream progress and open-bin pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open fresh bins more readily early on; late in stream, consolidate harder.
        score = 70.0 + 0.6 * mean_residual - 25.0 * (1.0 - progress) - 1.5 * open_bins_count as f64;
        // If some open bin leaves a near-perfect fit, opening fresh is bad.
        if frac < 0.05 {
            score += 20.0;
        }
        // If the next item is large and no open bin can hold it, opening is safer.
        if next_item_size > 0 && next_item_size > bin_residual - item_size && item_size < bin_residual {
            score -= 5.0;
        }
    }

    // Best-fit bias toward bins tighter than the mean.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + norm_pr) * (1.0 - progress + progress * norm_pr);
    score += 4.0 * poly * cap * 0.25;
    // penalize large dead space more as stream matures
    score += (norm_pr * norm_pr) * 20.0 * (0.5 + progress);
    // reward tight fits
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: favor bins whose residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }
    // new-bin candidate: mildly penalize early, allow late when residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - norm_pr).abs();
        score += 8.0 - 10.0 * progress - 5.0 * frag;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, warped by stream progress.
    let mut score = pr * (1.0 + 0.4 * progress);

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Non-linear penalty on small residuals (dead space), stronger late in stream.
    let dead = (-pr_norm * (1.0 - pr_norm)).max(0.0);
    score += 12.0 * dead * (0.3 + 0.7 * progress);

    // Reward tight fits with quadratic coupling to progress.
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 20.0 * progress;
    }

    // Two-step lookahead: chain placement reward scaled by tightness.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let chain_tightness = nxt / (pr + 1.0);
            score -= 40.0 + 60.0 * chain_tightness * (0.5 + 0.5 * progress);
            let second_post = pr - nxt;
            if second_post < 10.0 {
                score -= 30.0;
            } else if second_post < 25.0 {
                score -= 10.0;
            }
        } else {
            let gap = nxt - pr;
            if gap <= 10.0 {
                // Near miss: dead space that almost hosted the next item.
                score += 25.0 + 0.5 * pr;
            } else {
                score += 0.3 * pr;
            }
        }
    }

    // Prefer filling the fullest bins: deviation from mean residual.
    score += 0.35 * (mean_residual - pr);

    // New-bin candidate: costly by default, but attractive when it enables
    // a clean two-item chain (item + next item fill a fresh bin).
    if bin_residual == bin_capacity {
        let mut base = 150.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let leftover = bin_capacity - item_size - next_item_size;
            base -= (100 - leftover) as f64 * 1.8;
            if leftover == 0 {
                base -= 140.0;
            }
        }
        if next_item_size == 0 {
            if item_size == bin_capacity {
                base -= 500.0;
            } else {
                base += 200.0;
            }
        }
        base += 40.0 * progress;
        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        score += base;
    }

    // Coupling with open bins count: many open bins -> prefer consolidating.
    score += 0.06 * open_bins_count as f64 * pr_norm;

    // Bonus for bins whose residual exactly matches the next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0 * (0.5 + 0.5 * progress);
    }

    // Triangular dead-space kernel: penalize residuals too small to host the
    // next item but nonzero; peak penalty at ~half the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            let ratio = pr / nxt;
            score += 18.0 * ratio * (1.0 - ratio) * (0.4 + 0.6 * progress);
        }
    }

    // Reward bins whose residual after placement stays above a usable floor.
    if post_residual >= 25 && post_residual < bin_capacity {
        score -= 8.0 * (0.4 + 0.6 * progress);
    }

    // Strong consolidation pressure when many bins are open.
    if open_bins_count > 6 {
        score += 0.9 * pr_norm * (open_bins_count as f64).min(20.0);
    }

    // Near-perfect chain: residual after placement fits next item with tiny slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack2 = post_residual - next_item_size;
        if slack2 <= 3 {
            score -= 35.0 + 25.0 * progress;
        }
    }

    // Gen-13 mutation: three-item lookahead proxy — reward placements that leave
    // a residual matching the next item plus a small margin, enabling chained
    // fills and reducing dead space in later steps.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        // Ideal leftover is small but non-zero and divisible-friendly.
        if after_next >= 1 && after_next <= 15 {
            score -= 12.0 * (1.0 - after_next as f64 / 16.0) * (0.5 + 0.5 * progress);
        }
        // Penalize residuals that are prime-like awkward leftovers (hard to fill):
        // even residuals pair better with typical even item sizes.
        if after_next % 2 == 1 && after_next > 3 {
            score += 4.0;
        }
    }

    // Gen-13 mutation: late-stream tightness escalation — as the stream ends,
    // push harder toward zero-waste placements to squeeze out final bins.
    if progress > 0.75 {
        score += 6.0 * pr_norm;
        if post_residual <= 5 && post_residual > 0 {
            score -= 15.0;
        }
    }

    score
}

