        if open_bins_count > 8 && progress > 0.5 {
            base -= 30.0;
        }
        score += base;
    }

    // GEN 14 mutation: residual-entropy minimization. Penalize residuals that
    // fall in the "awkward zone" — too small for typical items (<= 30) but
    // nonzero — with intensity coupled to stream progress and open-bin count.
    if post_residual > 0 && post_residual <= 30 {
