}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in classes of 10
    let dead_class = post_residual / 10;
    // Penalize residual classes that are hard to fill (1..9, 11..19 etc. -> small residuals)
    if post_residual > 0 {
        let small = if post_residual < 10 { 1.0 } else { 0.0 };
        score += small * 15.0;
        // modulo structure: residuals of form 0 mod 10 are ideal
        if post_residual % 10 == 0 { score -= 6.0; }
        else { score += (post_residual % 10) as f64 * 0.4; }
    } else {
        score -= 12.0; // perfect fit
    }

    // Deep dead-space penalty for very small unusable residuals
    if post_residual > 0 && post_residual <= 5 {
        score += 20.0;
    }

    // Fit tightness: reward minimizing waste relative to item size
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 { score -= 25.0; }
        else if slack % 10 == 0 { score -= 15.0; }
        else { score -= 8.0 - slack as f64 * 0.2; }
    } else if next_item_size > post_residual {
        // next item cannot follow here; penalize slightly more when this bin was the only option
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer new bin only when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let early = (step_index as f64) / (total_items.max(1) as f64);
        // base cost of a fresh bin, reduced later in the stream when fragmentation is high
        score = bin_capacity as f64 * 0.85 - pressure * 2.0 - early * 10.0;
        if mean_residual > item_size as f64 + 10.0 {
            score += 15.0; // open bins still have room; don't open new
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (fill crowded bins first)
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
