    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling with open-bin pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0 + progress * 10.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // Opening a new bin is fine for huge items leaving tiny gaps.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
    } else {
        // Reward filling already-open bins, scaled by fullness.
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
