pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post-residuals that can't fit typical items are wasted,
    // but very small post-residuals (< 10) are essentially perfect closures.
    if post_residual > 0 {
        let dead = if post_residual < 10 { -20.0 } else { (post_residual as f64).powf(1.4) * 0.15 };
        score += dead;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead (k=2): reward if the next item fits into the post-residual (chaining),
    // penalize if next item is large and would be stranded.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 0.1 * (next_item_size - post_residual) as f64;
        }
        // Perfect pairing: item + next item exactly fills residual
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins; when residuals are fragmented, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of open bins and progress.
        score += 20.0 + 10.0 * progress + 0.3 * open_bins_count as f64;
        // But if mean residual is very low (all bins nearly full), opening new bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
        // Never open a new bin for a tiny item when a decent fit exists.
        if item_size < bin_capacity as f64 * 0.35 {
            score += 15.0;
        }
    } else {
        // Existing bin: slight reward for reducing mean residual dispersion.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.08 * dev;
    }

    // Time horizon: late in the stream, be more conservative with new bins.
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

