pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, weighted non-linearly by stream progress
    let mut score = pr * (0.5 + 1.5 * progress * progress);

    // Non-linear coupling: squared normalized residual with progress modulation
    score += (norm_pr * norm_pr) * cap * (0.3 + 0.7 * progress);

    // Cubic interaction: small residuals are dead space, especially late in stream
    score += (norm_pr * norm_pr * norm_pr) * cap * (1.0 - progress);

    // Reward tight fits (small post_residual) with smooth exponential decay
    score -= 20.0 * (-(pr / 15.0) * (pr / 15.0));

