    // Lookahead: reward if next item fits the post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        let slack = (pr - next_item_size as f64).abs();
        score -= fits * 10.0 * (-slack / 40.0);
        score += (1.0 - fits) * 5.0;
    }

    // Mild penalty proportional to open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5 * progress;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += ((pr - mean_residual) / cap).abs() * 8.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bins mildly attractive only for large items
    if bin_residual == bin_capacity {
        score = pr + 5.0 - item_size as f64 * 0.4;
    }

    score
}

