pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity wasted
    let waste_frac = post / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Harmonic bonus: post_residual divisible by 10, 20, 25, 50 => leftover reusable
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 4.0; }
        if pr % 50 == 0 { harmonic_bonus += 6.0; }
        // Perfect fit
        if pr == 0 { harmonic_bonus += 25.0; }
    }
    score -= harmonic_bonus;

    // Integer-division threshold on post_residual: dead space bands
    // post_residual < 10 is essentially dead space (min item size 1, but small slivers waste)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Mid-band residual (10..=30) is moderately useful
    if post_residual >= 10 && post_residual <= 30 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit exactly in the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += 0.15 * slack;
