    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are badly fragmented
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: slightly worse than a decent fit
        score = cap * 0.55;
        // If existing bins are fragmented (high mean residual spread), fresh bin is fine
        let frag = (mean_residual - post).abs();
        if frag > 40.0 {
            score -= 10.0;
