        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: discourage opening yet another
        score += 2.0 * open_bins_count as f64;
    }

    // Mild pressure to fill bins tightly when many bins are open
    score += 0.05 * open_bins_count as f64 * waste_frac;

    score
}

