    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small for the
    // smallest plausible item are wasted forever -> heavy penalty.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 40.0;
    }
    // Penalize very small usable gaps less, but still discourage fragmentation
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (small post_residual) nonlinearly
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 / bin_capacity as f64 * 5.0;

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening/spreading into new bins.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when existing bins would leave bad gaps
    if bin_residual == bin_capacity {
        // base penalty so we don't open bins frivolously
        score += 10.0;
        // relax penalty when few bins fit the item (last-chance pressure)
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size as f64 > post_residual as f64 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to use the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item can't use the gap -> gap likely dead
        score += 6.0;
    }

    // Stream progression: early on, be more willing to open bins; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins with residual close to mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Reward near-perfect compaction explicitly.
        score -= 120.0 / (post_residual as f64 + 2.0);
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            // Keep a usable second gap if possible.
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Dead-space guard: penalize placements that strand unusable slivers
    // relative to both current and upcoming item sizes.
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowded-field residual alignment: among many fitting bins, prefer
    // residuals close to the mean (avoids leaving outliers half-used).
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Only open a new bin when existing bins are very crowded.
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += 15.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // Big items justify a fresh bin; also allow opening when the stream
        // has plenty of remaining items to fill the new bin with.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
        let remaining = total_items.saturating_sub(step_index) as f64;
        score -= 0.05 * remaining;
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere else. Empty-bin candidate gets a baseline cost
    // proportional to wasted capacity of the whole bin.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Opening a new bin is more attractive early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If many bins fit, prefer using an existing one.
        score += 8.0 * fitting_bins_count as f64;
        // Lookahead: if the next item would also fit nicely in a fresh bin,
        // opening is more justified.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 6.0;
        }
        return score;
    }

    // Perfect fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward when post_residual matches next_item_size
    // exactly (item+next fill the bin completely).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item can follow: reward proportional to tightness of match.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover: penalize dead space,
            // scaled by how large the unusable gap is relative to item size.
            score += 0.5 * diff;
        }
    }

    // Reward bins tighter than the mean residual (good packing candidates).
    score -= 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post residual is huge waste).
    if fitting_bins_count == 1 {
        score -= 30.0;
        if post_residual > 40 {
            score += 0.4 * (post_residual as f64 - 40.0);
        }
    }

    // Prefer bins with smaller residual overall (best-fit bias).
    score += 0.3 * post_residual as f64;

    // Slight preference for consolidating when many bins are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

