    // Time horizon: early on, be more exploratory (favor new bins slightly);
    // late in the stream, tighten packing and avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
