        score = bin_capacity as f64;
        score -= 20.0 * (1.0 - progress);                 // cheaper to open early
        score += 60.0 * progress;                          // expensive late
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0;                                 // new bin useful for big next item
