    // Global residual coupling: if mean residual is high, prefer bins below mean
    // (drain the emptier ones), else prefer bins above mean (fill fullest).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev * (if mean_residual > bin_capacity as f64 * 0.5 { 1.0 } else { -1.0 });

    score
}

