            score += 25.0;
        }
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Strong compaction reward for small nonzero residuals
        score -= 120.0 / (post_residual as f64 + 2.0);
        if post_residual > item_size && post_residual < bin_capacity / 4 {
            score += 0.15 * post_residual as f64;
        }
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
    }

    // Dead-space guard: strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0;
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    score += 0.6 * open_bins_count as f64;

    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
    } else {
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
        // Mirror-companion rewards: exact and near-half residuals
        if post_residual * 2 == bin_capacity {
            score -= 15.0;
        }
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is divisible by
    // small "harmonic" divisors are more reusable, so reward them.
    if post_residual > 0 {
        let mut bonus = 0.0;
        if post_residual % 10 == 0 { bonus += 8.0; }
        if post_residual % 5 == 0 { bonus += 3.0; }
        if post_residual % 25 == 0 { bonus += 6.0; }
        if post_residual % 20 == 0 { bonus += 4.0; }
        // Perfect-fill reward
        if post_residual == 0 { score -= 40.0; }
        score -= bonus;
    } else {
        score -= 60.0; // exact fit is ideal
    }

    // Penalize small unusable dead space (post_residual in awkward range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space class
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // harmonic check: does next item leave a nice residual too?
        let nr = post_residual - next_item_size;
        if nr % 10 == 0 { score -= 6.0; }
    } else if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        // next item won't fit here; penalize leaving medium residual
        score += 5.0;
    }

    // Prefer tighter bins: closeness of item to residual (good fit fraction)
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // New-bin candidate handling: only attractive late in stream or when
    // open bins are on average too full to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // opening a new bin is penalized early, less so when open bins are crowded
        let open_penalty = 18.0 * (1.0 - progress) + 20.0 * avg_fullness * open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score = 60.0 + open_penalty - (if fitting_bins_count == 0 { 25.0 } else { 0.0 });
    }

    score
}

