        }
    } else if next_item_size > 0 && post_residual > 0.0 {
        // Dead space penalty if the leftover can't fit the lookahead item.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Crowding adjustment: when many bins are open, prefer consolidating into
    // bins that deviate below the mean residual (i.e., already tight bins).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // New-bin candidate handling: penalize opening a fresh bin, but relax the
    // penalty late in the stream or when the item is large (poor fit prospects).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 20.0;
        penalty -= 10.0 * progress;
        penalty -= 0.1 * item_size as f64;
        // If no open bin fits well (high mean residual waste), opening is fine.
        if mean_residual < item_size as f64 {
