    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving medium dead space.
        score += 6.0;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (post_residual as f64 / bin_capacity as f64) * progress;

    // Mean residual coupling: if open bins are already loose, discourage
    // leaving more slack.
    if post_residual as f64 > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Relative tightness: reward leaving a small fraction of the bin empty.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Smooth compaction reward: strongly favor small nonzero residuals.
        score -= 120.0 / (post_residual as f64 + 2.0);
        // Quadratic dead-space pressure for medium gaps that are hard to fill.
        if post_residual > item_size && post_residual < bin_capacity / 4 {
            score += 0.15 * post_residual as f64;
        }
        // Reward residuals that tile perfectly with future items.
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        // NEW: reward residuals that also tile with the next item size.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    }

    // Dead-space guard: penalize placements that strand unusable slivers.
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            // Keep a usable second gap if possible.
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 12 {
                score -= 30.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                // Partial third-fill potential reward.
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            // Triple-fill lookahead — can a third item also land here?
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // When many bins fit the item, pull residuals toward the mean.
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Only open a new bin when existing bins are very crowded.
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Remaining stream length pressure: fresh bins are cheaper early.
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Very large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // If the next item is large and few bins could host it, opening
        // a fresh bin now preserves large contiguous space for it.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Reserve fresh bins when the current item nearly fills one anyway.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // NEW: if no open bin can host the item at all, force a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        // Exact-fill lookahead — reward bins where item + next item
        // would leave near-zero residual (two-item compaction).
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
        // Reward bins that become exactly half-full, leaving room
        // for a mirror-sized companion item.
        if post_residual * 2 == bin_capacity {
            score -= 15.0;
        }
        // Reward near-half residuals (±2) for flexible companion packing.
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

