            // next item cannot fit here; dead space risk scales with post_residual
            score += post_residual as f64 * 0.3;
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.0;
    }

    // Prefer bins whose residual is below mean residual (well-packed bins)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space), unless it equals next item
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 20.0;
    }

    // Early in stream: mildly prefer opening/using fresh bins to keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress; // new bin cost grows as stream progresses
    }

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

