    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals in "useful" small classes
    // (likely fillable by future items) are rewarded; large dead zones penalized.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
