        score -= 25.0;
    } else if pr < quarter {
        // Mid class: neutral-ish, mild reward.
        score -= 8.0;
    } else if pr < bin_capacity / 2 {
        // Half-bin leftover: moderate dead space risk.
        score += 10.0;
    } else {
        // Large leftover: wasteful unless bin was nearly empty anyway.
        score += 22.0;
    }

