    // "class-aligned" with typical item sizes (multiples of 10).
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // round residual matches harmonic item grid
    }
    if pr > 0 && pr < 10 {
        score -= 12.0; // sub-smallest-item dead space is harmless
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement chains beautifully.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < sixteenth {
                score -= 18.0;
            } else if slack < quarter {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here after this placement: slight penalty
            // proportional to overflow amount.
            score += ((next_item_size - pr) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / cap_f < 0.25;
        let big_item = (item_size as f64) / cap_f > 0.6;
        if crowded || big_item || open_bins_count == 0 {
            score -= 30.0 + 15.0 * progress;
        } else {
            score += 25.0; // prefer filling existing bins early on
        }
    }

