    let cap = bin_capacity as f64;

    // Class of post_residual: which "harmonic slot" does the leftover fall into?
    // Small leftovers (<= 20) are near-perfect fills; large leftovers are wasteful.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else if post_residual <= 30 {
        score -= 6.0;
    } else if post_residual <= 50 {
        score += 8.0; // half-filled bin: mediocre
    } else {
        score += 20.0; // mostly empty bin used for a small item: wasteful
    }

    // Modulo-10 harmonic classes of the leftover: leftovers divisible by 10
    // pair naturally with common item sizes (multiples of 10 dominate typical streams).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 7.0;
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let waste_next = post_residual - next_item_size;
            if waste_next <= 10 {
                score -= 22.0;
            } else if waste_next <= 25 {
                score -= 8.0;
            } else {
                score += 10.0; // next item would leave a big hole
            }
        } else {
            // next item cannot use this bin's leftover: leftover becomes dead space
            score += (post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins is bad. Penalize the fresh bin mildly, scaled by how
    // much of it the item consumes.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        score += 15.0 + 40.0 * (1.0 - fill_frac); // small items in new bins are very bad
        if fitting_bins_count > 0 {
            score += 12.0; // there exist open bins that fit; prefer them
        }
    } else {
        // Favor bins that are already partially filled when alternatives exist
        let used_frac = 1.0 - bin_residual as f64 / cap;
        score -= 12.0 * used_frac;
    }

    // Mean-residual coupling: when open bins are on average quite full,
    // filling them further is extra valuable.
    if mean_residual < 25.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Stream progression: early on, keep bins open and flexible (penalize tight fills
    // slightly less over time as consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

