            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // When many bins fit the item, pull residuals toward the mean.
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Remaining stream length pressure: fresh bins are cheaper early.
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Very large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // Preserve large contiguous space for a large upcoming item.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Reserve fresh bins when the current item nearly fills one anyway.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // If no open bin can host the item at all, force a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // When remaining stream is long and mean fill is low,
        // suppress new-bin opening further to force compaction of existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        // NEW: suppress new-bin opening when any open bin leaves a small
        // post-residual (tight fit exists); fresh bins waste capacity.
        if fitting_bins_count >= 1 && item_size as f64 <= 0.95 * bin_capacity as f64 {
            score += 8.0;
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits (scaled by progress).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        // Exact-fill lookahead: item + next item exactly fills the bin.
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
        // NEW: progressive compaction bias — as the stream advances, tighten
        // residual selection harder so late placements fill bins completely.
        if post_residual > 0 {
            score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
        }
        // NEW: when few bins can host the item, reward the tightest fit extra.
        if fitting_bins_count <= 2 && post_residual > 0 {
            score -= 12.0 / (post_residual as f64 + 1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized,
    // since typical items are >= 10 and such gaps become permanently wasted.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 9.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size (low post_residual / item_size ratio).
    let tightness = pr / (item_size as f64).max(1.0);
    score -= 15.0 * (1.0 - tightness.min(1.0));

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item can use this bin's post-residual,
    // reward leaving that much space; otherwise penalize mismatched leftovers.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n && (post_residual as f64 - n) < 10.0 {
            score -= 20.0; // next item will fit snugly here
        } else if post_residual > 0 && post_residual < next_item_size as u32 {
            score += 8.0; // leftover too small for the known next item
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Penalize it mildly, but less when mean residual is small
    // (open bins are nearly full) or many bins are open (diversity useful).
    if bin_residual == bin_capacity {
        let base = 18.0;
        let relief = if mean_residual < 10.0 { 12.0 } else { 0.0 };
        score += base - relief + 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
