        // has plenty of remaining items to fill the new bin with.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
        let remaining = total_items.saturating_sub(step_index) as f64;
        score -= 0.05 * remaining;
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.3 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
