    // residual selection harder so late placements fill bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // When few bins can host the item, reward the tightest fit extra.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score -= 10.0 / (post_residual as f64 + 1.0);
    }

    // MUTATION: hard small-residual magnet — extra reward for residuals that
    // can still host a mid-size follow-up item, pushing toward near-full bins.
    if post_residual > 0 && post_residual <= 25 {
        score -= 14.0 - 0.4 * post_residual as f64;
    }

    // MUTATION: penalize residuals just below the next item size by a narrow
    // margin (wasted space that could have hosted the next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
