        let urgency = (remaining / 200.0).min(1.0) ;
        let mut new_bonus = 15.0 + 0.05 * remaining ;
        if fill_ratio > 0.85 {
            new_bonus -= 10.0 ;
        }
        // discourage opening fresh bins when many bins can still absorb items
        if fitting_bins_count > 3 && fill_ratio < 0.5 {
            new_bonus -= 8.0 * urgency ;
        }
        // when the mean leftover across bins is small, existing bins are tight:
        // a new bin is less attractive
        if mean_residual > 0.0 && (mean_residual as u32) >= item_size * 2 {
            new_bonus += 5.0 ;
        } else {
            new_bonus -= 4.0 * urgency ;
        }
        score -= new_bonus ;
    }
    // dead-space guard: penalize placements that strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size } ;
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64 ;
    }
    // prefer near-perfect compaction: reward small post_residual explicitly
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0) ;
        // extra reward when the leftover could still hold the next item snugly
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 / (post_residual as f64 - next_item_size as f64 + 1.0) ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize post-residuals that are small but unusable (dead space wedge).
    // A residual is "usable" if it can still hold a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: nothing (min size 1..100 unknown, but small slivers are risky)
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement creates a perfect chain — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 8.0; // chain possible
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer a new bin when existing fits are very poor (large post_residual
    // would be created) and there is still plenty of stream left.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins early/mid stream; relax near the end.
        score += 30.0 * (1.0 - progress);
        // If many bins are open with slack, discourage one more.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward using already-open bins, more so when many are open.
        score -= 5.0 * (open_bins_count as f64).sqrt().min(8.0);
    }

    // Global balance: prefer bins whose residual is near the mean (keeps
    // residuals homogeneous, improving future packing flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight time-varying exploration pressure: early on, be more tolerant
    // of imperfect fits to spread items; later, be greedy.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Relative tightness: reward leaving a small fraction empty.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Smooth compaction reward: strongly favor small nonzero residuals.
        score -= 120.0 / (post_residual as f64 + 2.0);
        // Quadratic dead-space pressure for medium gaps that are hard to fill.
        if post_residual > item_size && post_residual < bin_capacity / 4 {
            score += 0.15 * post_residual as f64;
        }
        // Reward residuals that tile perfectly with future items.
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        // Reward residuals that also tile with the next item size.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Half-capacity mirror bonus.
        if post_residual * 2 == bin_capacity {
            score -= 15.0;
        }
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 6.0;
        }
        // NEW: progressive compaction bias — tighten late placements harder.
        score += 6.0 * progress * frac;
        // NEW: reward near-perfect residuals more aggressively late in stream.
        score -= (1.0 - progress) * 20.0 / (post_residual as f64 + 1.0);
    }

    // Dead-space guard: penalize placements that strand unusable slivers.
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // When many bins fit the item, pull residuals toward the mean.
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // NEW: when few bins can host the item, reward the tightest fit extra.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score -= 10.0 / (post_residual as f64 + 1.0);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += 15.0 * progress;
        // Remaining stream length pressure: fresh bins are cheaper early.
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Very large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // Preserve large contiguous space for a large upcoming item.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Reserve fresh bins when the current item nearly fills one anyway.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // If no open bin can host the item at all, force a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // When remaining stream is long and mean fill is low,
        // suppress new-bin opening further to force compaction of existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        // NEW: if some open bin leaves a residual exactly matching the item
        // plus next item, strongly discourage opening a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_residual {
            score += 12.0;
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        // Exact-fill lookahead: item + next item exactly fills the bin.
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
        // NEW: exact two-item fill bonus (item + next fills residual exactly).
        if next_item_size > 0 && item_size + next_item_size == bin_residual {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic coupling of post residual with progress
    let mut score = pr * (1.0 + 0.8 * progress * pr_norm);

    // Cubic penalty for tiny dead space, growing with progress
    score += 40.0 * progress * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Interaction with mean residual: prefer bins whose residual deviates favorably
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * dev * (0.5 + progress);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap) * (0.3 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.5 * open_bins_count as f64 * pr_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    if post_residual == 0 {
        score -= 1000.0;
    }
    if next_item_size > 0 {
