            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 14.0;
            } else if second_post == next_item_size {
                score -= 10.0;
            }
            // lookahead: can the next TWO items both chain?
            let second_fit = post_residual >= item_size + next_item_size;
            if second_fit {
                score -= 12.0;
            }
        } else {
            let waste = post_residual as f64;
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 25.0 + waste * 0.5;
            } else {
                score += waste * 0.3;
            }
        }
    }
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }
    if bin_residual == bin_capacity {
        score -= 15.0 + 0.05 * (total_items.saturating_sub(step_index)) as f64;
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
        // open a fresh bin for large items when existing bins are mostly full
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < 0.35 * bin_capacity as f64 {
            score -= 6.0;
        }
    }
    // dead-space guard: penalize placements that strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }
    // prefer near-perfect compaction: reward small post_residual explicitly
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0);
        // extra nudge toward exact-halving residuals, which chain well
        if post_residual * 2 == bin_residual {
            score -= 5.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Leftovers in the "dead zone" (small, hard
    // to fill) are penalized; leftovers in "harmonic" buckets (nice fractions
    // of capacity) are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Integer division thresholds: which eighth of the capacity does the
    // leftover fall into? Classes 0..=7.
    let class = (post_residual * 8) / bin_capacity; // 0..=7

    match class {
        // leftover < 12.5% of capacity: nearly dead space -> strong penalty
        0 => score += 12.0 * (1.0 - frac),
        // 12.5%..25%: poor but sometimes fillable with tiny items
        1 => score += 4.0,
        // 25%..37.5% and 37.5%..50%: harmonic quarter-ish zones, reward
        2 => score -= 3.0,
        3 => score -= 5.0,
        // 50%..62.5%: half-bin zone, very reusable -> big reward
        4 => score -= 7.0,
        // 62.5%..75%: good
        5 => score -= 4.0,
        // 75%..87.5% and 87.5%..100%: large leftovers, mild reward
        6 => score -= 2.0,
        _ => score -= 1.0,
    }

    // Modulo arithmetic on the leftover: leftovers divisible by common
    // small item sizes (10, 20, 25, 50) are "harmonic" and easy to close.
    let harmonics: [u32; 5] = [10, 20, 25, 40, 50];
    for h in harmonics.iter() {
        if post_residual % h == 0 && post_residual > 0 {
            score -= 2.0;
            break;
        }
    }

    // Exact fit: perfect closure, huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in the leftover,
    // strongly prefer this bin (chain the harmonic pair).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next item leaves another small leftover: mild penalty scaled
            // by how dead that next leftover would be
            let next_left = post_residual - next_item_size;
            if next_left < bin_capacity / 8 {
                score += 3.0;
            } else {
                score -= 1.5;
            }
        } else {
            // next item cannot go here anyway; if this is our last chance
            // bin, prefer using it rather than wasting it
            if fitting_bins_count == 1 {
                score -= 6.0;
            }
        }
    }

    // Last-chance bonus: if only this bin fits, avoid opening a new bin
    // unless the leftover would be truly dead.
    if fitting_bins_count == 1 && post_residual >= bin_capacity / 8 {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin has huge residual, so the
    // base score already favors it for big items. Penalize opening a new
    // bin when the stream is late and many bins are already open, but
    // reward it early when consolidation is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // empty bin: penalize moderately; only wins when open-bin fits are bad
        score += 10.0 + 15.0 * (1.0 - progress);
        if item_size as f64 / cap > 0.5 {
            // big items deserve fresh bins to avoid fragmenting
            score -= 12.0;
        }
    }

    // Slight preference for bins whose residual is below the mean
    // (consolidate fuller bins first, keeping large-capacity bins open).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
