        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Only open a new bin when existing bins are very crowded.
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Remaining stream length pressure: opening bins late is wasteful.
        score += 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits (softer weight to
        // let residual-dead-space terms dominate).
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from many open bins: prefer reusing existing bins over opening new ones.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: make empty bins unattractive unless item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.3;
    }

    // Lookahead: if next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Relative tightness: reward leaving a small fraction empty.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Smooth compaction reward: strongly favor small nonzero residuals.
        score -= 120.0 / (post_residual as f64 + 2.0);
        // Quadratic dead-space pressure for medium gaps that are hard to fill.
        if post_residual > item_size && post_residual < bin_capacity / 4 {
            score += 0.15 * post_residual as f64;
        }
        // Reward residuals that tile perfectly with future items.
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        // Reward residuals that also tile with the next item size.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Half-capacity mirror bonus.
        if post_residual * 2 == bin_capacity {
            score -= 15.0;
        }
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 6.0;
        }
    }

    // Dead-space guard: penalize placements that strand unusable slivers.
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // When many bins fit the item, pull residuals toward the mean.
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Remaining stream length pressure: fresh bins are cheaper early.
        score -= 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Very large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // Preserve large contiguous space for a large upcoming item.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Reserve fresh bins when the current item nearly fills one anyway.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // If no open bin can host the item at all, force a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // When remaining stream is long and mean fill is low,
        // suppress new-bin opening further to force compaction of existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        // Exact-fill lookahead: item + next item exactly fills the bin.
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
    }

    // Progressive compaction bias — as the stream advances, tighten
    // residual selection harder so late placements fill bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // When few bins can host the item, reward the tightest fit extra.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score -= 10.0 / (post_residual as f64 + 1.0);
    }

    // COMBINED MUTATION: two-step lookahead — if the residual left after
    // placing item + next item can still host a plausible follow-up item
    // (approximated by min of item/next sizes), reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let second_post = post_residual - next_item_size;
        let follow = item_size.min(next_item_size);
        if follow > 0 && second_post >= follow {
            let third_tightness = follow as f64 / (second_post as f64 + 1.0);
            score -= 10.0 * third_tightness;
        }
        // Penalize residuals that will strand exactly the amount that can
        // never be filled again (between 1 and follow-1 after two placements).
        if second_post > 0 && second_post < follow {
            score += 12.0;
        }
    }

    // Global smooth compaction reward (borrowed from best-known), applied
    // even when post_residual == 0 handled above; reinforces small residuals
    // in the mid-range where the dead-space tiers are too coarse.
    if post_residual >= 20 && post_residual < bin_capacity / 4 {
        score -= 0.4 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item still fits in the leftover space
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Reward proportional to tightness of the follow-up fit
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use the leftover: penalize dead space more strongly
    else if next_item_size > 0 {
        score += 15.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize creating tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect closure: bin exactly filled
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, reward using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously
        score += 30.0;
        // If few fitting bins or open bins are congested, new bin becomes viable
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        if (mean_residual - item_size as f64) < 5.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
