    // Prefer bins whose residual is close to item_size (best-fit flavor) with coupling to mean.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.3;

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    // Time-horizon modulation: early in stream, be conservative (higher score variance later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

