    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 1.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.3;
    }

    // Prefer bins below mean residual slightly (balance load)
    score += 0.1 * ((pr - mean_residual) / cap);

    // Mild penalty for many open bins to discourage needless fragmentation
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
    if post_residual == 0 {
        score -= 1000.0 ;
    }
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0) ;
            score -= 40.0 + 60.0 * chain_tightness ;
            let second_post = post_residual - next_item_size ;
