            } else if second_post < 20 {
                score -= 12.0 ;
            } else if second_post == next_item_size {
                score -= 8.0 ;
            }
            // extended lookahead: can the bin chain a third small item?
            if second_post >= 1 {
                let third_fit = second_post >= next_item_size || next_item_size <= 1 ;
                if !third_fit && second_post < next_item_size {
                    // stranded after two placements: mild penalty scaled by dead space
                    score += 0.25 * second_post as f64 ;
                }
            }
        } else {
            let waste = post_residual as f64 ;
            let gap = (next_item_size - post_residual) as f64 ;
            if gap <= 10.0 {
                score += 25.0 + waste * 0.5 ;
            } else {
                score += waste * 0.3 ;
            }
        }
    }
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual . max (0.0)) ;
    }
    if bin_residual == bin_capacity {
        score -= 15.0 + 0.05 * (total_items . saturating_sub (step_index)) as f64 ;
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0 ;
        }
        // opening a fresh bin is more attractive when existing bins are fragmented
        if fitting_bins_count <= 2 && next_item_size > 0 {
            score -= 6.0 + 0.4 * next_item_size as f64 ;
        }
    }
    // dead-space guard: penalize placements that strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size } ;
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64 ;
    }
    // prefer near-perfect compaction: reward small post_residual explicitly
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0) ;
    }
    // harmony bonus: residual exactly matches the next item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0 ;
    }
    // large items should avoid bins whose residual leaves an awkward mid-gap
    if item_size as f64 > 0.6 * bin_capacity as f64 && post_residual > 0 && post_residual < 8 {
        score += 10.0 ;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group dead space into capacity/8 buckets
    let class = post_residual / (bin_capacity / 8);
    score += class as f64 * 3.0;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Does the next item fit in the post residual? Reward that strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0;
            // Harmonic pairing: next item leaves small residue again
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 20.0;
            }
        } else {
            // Dead space that the lookahead cannot use: penalize by residue class
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 55.0;
        // But if open bins are all crowded (high mean residual), a new bin is fine
        let crowding = mean_residual / bin_capacity as f64;
        if crowding < 0.25 {
            score -= 40.0;
        }
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Small mod-based tiebreak on residual to spread placements
    score += (post_residual % 7) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Relative tightness: reward leaving a small fraction empty.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Smooth compaction reward: strongly favor small nonzero residuals.
        score -= 120.0 / (post_residual as f64 + 2.0);
        // Quadratic dead-space pressure for medium gaps that are hard to fill.
        if post_residual > item_size && post_residual < bin_capacity / 4 {
            score += 0.15 * post_residual as f64;
        }
        // Reward residuals that tile perfectly with future items.
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        // Reward residuals that also tile with the next item size.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Half-capacity mirror bonus.
        if post_residual * 2 == bin_capacity {
            score -= 15.0;
        }
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 6.0;
        }
    }

    // Dead-space guard: penalize placements that strand unusable slivers.
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            if second_post >= next_item_size.min(item_size) {
                score -= 6.0;
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // When many bins fit the item, pull residuals toward the mean.
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Simplified, stronger new-bin suppression (borrowed from best heuristic):
        // fresh bins are penalized proportionally to the remaining stream length.
        score -= 15.0 + 0.05 * (total_items.saturating_sub(step_index)) as f64;
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Very large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0;
        }
        // Reserve fresh bins when the current item nearly fills one anyway.
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // Preserve large contiguous space for a large upcoming item.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If no open bin can host the item at all, force a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // When remaining stream is long and mean fill is low,
        // suppress new-bin opening further to force compaction of existing bins.
        let remaining = total_items.saturating_sub(step_index);
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Reward bins whose post-residual still accommodates the next item
        // without leaving a stranded sliver.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
        }
        // Exact-fill lookahead: item + next item exactly fills the bin.
        if next_item_size > 0 && post_residual == 0 {
            score -= 50.0;
        }
    }

    // Progressive compaction bias — as the stream advances, tighten
    // residual selection harder so late placements fill bins completely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 {
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // When few bins can host the item, reward the tightest fit extra.
    if fitting_bins_count <= 2 && post_residual > 0 {
        score -= 10.0 / (post_residual as f64 + 1.0);
    }

    // NEW: multiplicative lookahead coupling — when the residual after placing
    // the next item would be tiny but nonzero, reward it proportionally to
    // progress, sharpening end-of-stream compaction.
    if next_item_size > 0 && post_residual > next_item_size {
        let second_post = post_residual - next_item_size;
        if second_post > 0 && second_post <= 5 {
            score -= (10.0 + 30.0 * progress) * (6.0 - second_post as f64) / 6.0;
        }
    }

    // NEW: synergy term — when the bin residual is tight relative to the item
    // AND the next item chains well, amplify the compaction reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fit_ratio > 0.8 {
            score -= 12.0 * fit_ratio;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
