            } else if second_post == next_item_size {
                score -= 8.0 ;
            }
            // third-order lookahead: if the chain leaves room for a third item, reward more
            if second_post >= item_size.min(next_item_size) {
                score -= 6.0 + 0.15 * second_post as f64 ;
            }
        } else {
            let waste = post_residual as f64 ;
            let gap = (next_item_size - post_residual) as f64 ;
            if gap <= 10.0 {
                score += 25.0 + waste * 0.5 ;
            } else {
                score += waste * 0.3 ;
            }
        }
    }
    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual . max (0.0)) ;
    }
    // scarcity coupling: when few bins can fit this item, favor using one of them
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 12.0 ;
    }
    if bin_residual == bin_capacity {
        // open a new bin only for large items or when open bins would strand dead space
        let remaining = (total_items . saturating_sub (step_index)) as f64 ;
        score -= 15.0 + 0.05 * remaining ;
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 10.0 ;
        }
        // discourage new bins when many open bins already fit the item well
        if fitting_bins_count > 3 && post_residual as f64 > 0.25 * bin_capacity as f64 {
            score += 20.0 ;
        }
    }
    // dead-space guard: penalize placements that strand unusable slivers
    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size } ;
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64 ;
        // harsher when the stranded sliver is tiny relative to capacity
        if (post_residual as f64) < 0.05 * bin_capacity as f64 {
            score += 10.0 ;
        }
    }
    // prefer near-perfect compaction: reward small post_residual explicitly
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0) ;
        // extra reward for residuals that exactly match plausible future items
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post residuals that are too small to be useful
    // for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the fit here is poor
    // or no good option exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // Fewer open bins -> cheaper to open a new one.
        score -= 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If the item would leave a very large residual in a fresh bin, opening
        // is wasteful; if item is large, fresh bin is fine.
        score += 0.3 * post_residual as f64;
    }

    // Lookahead coupling: if the next item could also fit in the post residual,
    // reward this placement (chaining two items in one bin).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else if (bin_residual as u32) >= next_item_size {
            // Next item fits this bin but current item blocks a better chain.
            score += 5.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling below-average-residual bins keeps larger residuals available.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference for filling already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let mut score = post_residual as f64 ;
