}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Normalize post-residual into [0,1] fraction of capacity
    let pf = post / cap;
    // Smooth polynomial coupling: penalize mid-range dead space quadratically, reward near-zero residual
    let poly = pf * pf * (3.0 - 2.0 * pf); // smoothstep shape in [0,1]
    score += 12.0 * poly * (0.5 + progress);

    // Strong reward for very tight fits (post_residual small)
    score -= 25.0 * (-post / 8.0).exp();

    // Last-chance bonus: only one fitting bin -> heavily favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize early, allow late when existing fit is poor
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 0.5 * mean_residual;
    }

    // Lookahead: if next item fits snugly in the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * progress;

    // Mean-residual coupling: prefer bins below the mean residual (tighter bins first)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
