        } else if second_post < 10 {
            score -= 30.0;
        } else if second_post < 20 {
            score -= 12.0;
        } else if second_post == next_item_size {
            score -= 8.0;
        }
        // Chain multiple future copies of the smaller of item/next sizes.
        let m = next_item_size.min(item_size).max(1);
        let mut k = 1u32;
        while second_post >= k * m && k <= 5 {
            score -= 6.0 / k as f64;
            k += 1;
        }
