        if post_residual >= 4 && post_residual % 4 == 0 {
            score -= 1.5;
        }
        // Stranded-slice guard: post residual smaller than next item.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            score += 4.0 * (next_item_size - post_residual) as f64 * (1.0 - progress);
