pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = total_items.saturating_sub(step_index);

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small useless gaps are heavily penalized.
        if post_residual < 10 {
            score += 60.0 * (1.0 - progress);
        } else if post_residual < 20 {
            score += 25.0;
        }
        // Relative tightness: reward leaving a small fraction of the bin empty.
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 20.0 * frac;
        // Divisibility bonuses: residual that tiles cleanly with item sizes.
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        // Small residual late in stream is wasted.
        if post_residual > 0 && post_residual < 8 {
            score += 2.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain tightness: favor residuals that tightly fit the next item.
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            // Keep a usable second gap if possible.
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0; // double perfect fit lookahead
            } else if second_post < 12 {
                score -= 30.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            // Multi-step chain: reward residual supporting several more items.
            let m = next_item_size.min(item_size).max(1);
            if second_post >= m { score -= 6.0; }
            if second_post >= 2 * m { score -= 4.0; }
            if second_post >= 3 * m { score -= 2.0; }
            if second_post >= 4 * m { score -= 1.5; }
            let chain_val = (m as f64) * (1.0 - 0.85_f64.powi((second_post / m) as i32 + 1));
            score -= 0.15 * chain_val * (1.0 - progress);
            // Third-item lookahead.
            if second_post >= next_item_size {
                let third = second_post - next_item_size;
                if third == 0 {
                    score -= 10.0;
                } else if third < next_item_size / 2 {
                    score -= 3.0;
                }
            }
        } else {
            // Placement strands the bin relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
            // Stranded sliver scaling with remaining stream.
            let remaining_frac = 1.0 - progress;
            score += 4.0 * gap * remaining_frac;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        // Only open a new bin when existing bins are very crowded.
        score -= 30.0 * crowded - 10.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += 15.0 * progress;
        // Long remaining stream: opening fresh is slightly costlier.
        score += 0.05 * remaining as f64;
        // If the item fits the next item chain poorly, don't open new bins.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        // If several bins fit the item, opening fresh bins is wasteful.
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        // Large items prefer a fresh bin to avoid fragmenting existing bins.
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        // Medium-large items also benefit from a fresh bin when the stream is early.
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // Big next item with no fitting bin: fresh bin preserves options.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Must open a new bin if nothing fits.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Early with loose bins: avoid opening more.
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        // Late stream: strongly prefer existing bins.
        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 30.0 * (progress - 0.7) / 0.3;
        }
        // Fresh bin supports exact next-item fit.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    } else {
        // Prefer tighter existing bins: penalize loose fits.
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        // Fill-based pressure that grows with progress.
        let fill = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 * fill + 3.0 * progress * fill;
        // Reward bins whose post-residual still accommodates the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 {
                score -= 8.0;
            }
            if slack == 0 {
                score -= 6.0;
            }
            if slack > 0 && slack < 6 {
                score -= 4.0 * (1.0 - progress) * (6.0 - slack as f64) / 6.0;
            }
        }
        // Tiny residual is nearly dead space.
        if post_residual > 0 && post_residual <= 3 {
            score -= 5.0;
        }
        // Small residual relative to capacity late: push toward closing bins.
        if post_residual > 0 && (post_residual as f64) < 0.12 * bin_capacity as f64 {
            score -= 3.0 * (1.0 - post_residual as f64 / (0.12 * bin_capacity as f64)) * (1.0 - progress);
        }
        // Late stream: prefer very full bins.
        if progress > 0.75 {
            score += 5.0 * fill * (progress - 0.75) / 0.25;
        }
        if progress > 0.85 && post_residual == 0 {
            score -= 10.0 * (progress - 0.85) / 0.15;
        }
    }

    // General tightness reward.
    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0);
    }

    score
}

