            score += 25.0;
        }
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 30.0 * (progress - 0.7) / 0.3;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && progress < 0.6 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
        if item_size as f64 >= 0.8 * bin_capacity as f64 && fitting_bins_count >= 1 && progress < 0.85 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < (next_item_size / 2) && fitting_bins_count >= 2 && progress < 0.8 {
            score -= 8.0;
        }
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // pairable large item with next: fresh bin helps
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && item_size as f64 > 0.5 * bin_capacity as f64 && remaining > 100 {
            score -= 5.0;
        }
        // only fitting bin would strand a sliver below adaptive floor
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < adaptive_floor && remaining > 50 {
            score -= 10.0 * (1.0 - post_residual as f64 / adaptive_floor.max(1) as f64);
        }
        if progress > 0.9 && crowded > 0.8 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if progress > 0.5 && fitting_bins_count >= 3 && post_residual > 0 && post_residual < 5 {
            score += 4.0;
        }
        if next_item_size > 0 && fitting_bins_count == 1 {
            if post_residual > 0 && post_residual < next_item_size {
                score += 12.0 + 0.2 * (next_item_size - post_residual) as f64;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < (next_item_size / 2) && remaining > 100 {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / (next_item_size / 2).max(1) as f64);
        }
    } else {
        let fill = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 * fill + 3.0 * progress * fill;
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 { score -= 8.0; }
            if slack == 0 { score -= 6.0; }
            if slack > 0 && slack < 6 {
                score -= 4.0 * (1.0 - progress) * (6.0 - slack as f64) / 6.0;
            }
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 5.0;
        }
        if progress > 0.75 {
            score += 5.0 * fill * (progress - 0.75) / 0.25;
        }
        if progress > 0.85 && post_residual == 0 {
            score -= 10.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.3 && progress < 0.85 && post_residual > 0 {
            let waste_frac = 1.0 - fill;
            score += 2.0 * waste_frac * (1.0 - progress);
        }
        // penalize residuals far from the crowd mean (outlier gaps)
        if fitting_bins_count > 3 && post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual.max(0.0)).abs();
            score += 0.05 * dev.min(30.0);
        }
        if progress > 0.4 && fill > 0.6 && post_residual > 0 {
            score -= 2.5 * fill;
        }
        if post_residual > 0 && (post_residual as f64) < 0.12 * bin_capacity as f64 {
            score -= 3.0 * (1.0 - post_residual as f64 / (0.12 * bin_capacity as f64)) * (1.0 - progress);
        }
    }

    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
        score += 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / usable_floor.max(1) as f64);
    }

    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
