pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let remaining = total_items.saturating_sub(step_index);
    let min_next = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    let adaptive_floor = ((min_next as f64).max(mean_residual.max(0.0) * 0.35).min(bin_capacity as f64 * 0.5)) as u32;

    if post_residual == 0 {
        score -= 1000.0;
    } else {
        if item_size > 0 && post_residual % item_size == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 6.0;
        }
        let half = bin_capacity / 2;
        if post_residual.abs_diff(half) <= 2 {
            score -= 5.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let remaining_frac = 1.0 - progress;
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            score += 4.0 * (next_item_size - post_residual) as f64 * remaining_frac;
        }
        if post_residual >= 4 && post_residual % 4 == 0 {
            score -= 1.5;
        }
        // modular reusability: post_residual nearly a multiple of next item
        if next_item_size > 0 && post_residual > next_item_size {
            let rem = post_residual % next_item_size;
            if rem <= 2 || rem + 2 >= next_item_size {
                score -= 3.0 * (1.0 - progress);
            }
        }
        if post_residual > 0 && post_residual < 8 {
            score += 2.0 * (1.0 - progress);
        }
    }

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_tightness = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 40.0 + 60.0 * chain_tightness;
            let second_post = post_residual - next_item_size;
            if second_post == 0 {
                score -= 80.0;
            } else if second_post < 10 {
                score -= 30.0;
            } else if second_post < 20 {
                score -= 12.0;
            } else if second_post == next_item_size {
                score -= 8.0;
            } else if second_post < 2 * next_item_size {
                score -= 0.1 * (2 * next_item_size - second_post) as f64;
            }
            let m = next_item_size.min(item_size).max(1);
            if second_post >= m { score -= 6.0; }
            if second_post >= 2 * m { score -= 4.0; }
            if second_post >= 3 * m { score -= 2.0; }
            if second_post >= 4 * m { score -= 1.5; }
            if second_post >= 5 * m { score -= 1.0; }
            let chain_val = (m as f64) * (1.0 - 0.85_f64.powi((second_post / m) as i32 + 1));
            score -= 0.15 * chain_val * (1.0 - progress);
            if second_post % 5 == 0 && second_post > 0 {
                score -= 2.0;
            }
            // third-item lookahead
            if second_post >= next_item_size {
                let third = second_post - next_item_size;
                if third == 0 {
                    score -= 10.0;
                } else if third < next_item_size / 2 {
                    score -= 3.0;
                }
            }
            if second_post > 0 && second_post < m / 2 {
                score += 6.0 * (1.0 - progress);
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 8.0 {
                score += 25.0 + post_residual as f64 * 0.5;
            } else {
                score += post_residual as f64 * 0.3;
            }
        }
    }

    if fitting_bins_count > 4 {
        score += 0.8 * (post_residual as f64 - mean_residual.max(0.0));
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    score += 0.6 * open_bins_count as f64;

    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let crowded = (mean_fill / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * crowded - 10.0;
        score += 15.0 * progress;
        score -= 0.05 * remaining as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
        if fitting_bins_count >= 2 {
            score += 25.0;
        }
        if item_size as f64 > 0.85 * bin_capacity as f64 {
            score -= 35.0;
        }
        if item_size as f64 >= 0.95 * bin_capacity as f64 {
            score -= 60.0;
        }
        if item_size as f64 >= 0.7 * bin_capacity as f64 {
            score -= 15.0;
        }
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if remaining > 200 && crowded < 0.5 {
            score += 20.0 * (0.5 - crowded);
        }
        if progress > 0.7 && fitting_bins_count >= 1 {
            score += 30.0 * (progress - 0.7) / 0.3;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && progress < 0.6 {
            score += 6.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 15.0;
        }
        if item_size as f64 >= 0.8 * bin_capacity as f64 && fitting_bins_count >= 1 && progress < 0.85 {
            score -= 12.0;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < (next_item_size / 2) && fitting_bins_count >= 2 && progress < 0.8 {
            score -= 8.0;
        }
        if item_size > bin_capacity / 2 && progress < 0.5 {
            score -= 12.0;
        }
        // fresh bin pairs well when item + next fits exactly
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && item_size as f64 > 0.5 * bin_capacity as f64 && remaining > 100 {
            score -= 5.0;
        }
        // sole fitting bin with stranded sliver: prefer fresh bin
        if fitting_bins_count == 1 && post_residual > 0 && post_residual < adaptive_floor && remaining > 50 {
            score -= 10.0 * (1.0 - post_residual as f64 / adaptive_floor.max(1) as f64);
        }
        if progress > 0.9 && crowded > 0.8 && fitting_bins_count >= 1 {
            score += 15.0;
        }
        if progress > 0.5 && fitting_bins_count >= 3 && post_residual > 0 && post_residual < 5 {
            score += 4.0;
        }
        if next_item_size > 0 && fitting_bins_count == 1 {
            let only_post = post_residual;
            if only_post > 0 && only_post < next_item_size {
                score += 12.0 + 0.2 * (next_item_size - only_post) as f64;
            }
        }
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < (next_item_size / 2) && remaining > 100 {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / (next_item_size / 2) as f64);
        }
    } else {
        let fill = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 4.0 * fill + 3.0 * progress * fill;
        score += 0.25 * (bin_residual as f64 - item_size as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack >= 12 { score -= 8.0; }
            if slack == 0 { score -= 6.0; }
            if slack > 0 && slack < 6 {
                score -= 4.0 * (1.0 - progress) * (6.0 - slack as f64) / 6.0;
            }
        }
        if post_residual > 0 && post_residual <= 3 {
            score -= 5.0;
        }
        if progress > 0.75 {
            score += 5.0 * fill * (progress - 0.75) / 0.25;
        }
        if progress > 0.85 && post_residual == 0 {
            score -= 10.0 * (progress - 0.85) / 0.15;
        }
        if progress > 0.3 && progress < 0.85 && post_residual > 0 {
            let waste_frac = 1.0 - fill;
            score += 2.0 * waste_frac * (1.0 - progress);
        }
        // mildly prefer bins whose post residual deviates from mean waste (diversity of gap sizes)
        if fitting_bins_count > 3 && post_residual > 0 {
            let dev = (post_residual as f64 - mean_residual.max(0.0)).abs();
            score += 0.05 * dev.min(30.0);
        }
        if progress > 0.4 && fill > 0.6 && post_residual > 0 {
            score -= 2.5 * fill;
        }
        if post_residual > 0 && (post_residual as f64) < 0.12 * bin_capacity as f64 {
            score -= 3.0 * (1.0 - post_residual as f64 / (0.12 * bin_capacity as f64)) * (1.0 - progress);
        }
    }

    let usable_floor = if next_item_size > 0 { next_item_size.min(item_size) } else { item_size };
    if post_residual > 0 && post_residual < usable_floor {
        score += 18.0 + 0.35 * post_residual as f64;
        score += 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / usable_floor.max(1) as f64);
    }

    if post_residual > 0 {
        score -= 120.0 / (post_residual as f64 + 2.0);
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
